export type TokenKind = "num" | "word" | "lbr" | "rbr";

export interface Token {
  kind: TokenKind;
  text: string;
  /** Lower-cased word, for case-insensitive comparison. */
  key: string;
  value: number;
  line: number;
  column: number;
}

const isSpace = (c: string) => c === " " || c === "\t" || c === "\n" || c === "\r";
const isDigit = (c: string) => c >= "0" && c <= "9";
const isWordStart = (c: string) => /[\p{L}_]/u.test(c);
const isWordChar = (c: string) => /[\p{L}\p{N}_]/u.test(c);

export function lex(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let lineStart = 0;
  const push = (kind: TokenKind, start: number, end: number, value = 0) => {
    const text = source.slice(start, end);
    tokens.push({ kind, text, key: text.toLowerCase(), value, line, column: start - lineStart + 1 });
  };
  while (i < source.length) {
    const c = source[i];
    if (c === "\n") {
      i++;
      line++;
      lineStart = i;
      continue;
    }
    if (isSpace(c)) {
      i++;
      continue;
    }
    const start = i;
    if (isDigit(c)) {
      while (i < source.length && isDigit(source[i])) i++;
      push("num", start, i, Number(source.slice(start, i)));
      continue;
    }
    if (isWordStart(c)) {
      while (i < source.length && isWordChar(source[i])) i++;
      push("word", start, i);
      continue;
    }
    if (c === "[") {
      i++;
      push("lbr", start, i);
      continue;
    }
    if (c === "]") {
      i++;
      push("rbr", start, i);
      continue;
    }
    i++;
  }
  return tokens;
}
EOF
