import type { Token } from "./lexer";

export type Expr = { kind: "num"; value: number; at: Token };

export type Stmt =
  | { kind: "move"; sign: 1 | -1; arg: Expr; at: Token }
  | { kind: "turn"; sign: 1 | -1; arg: Expr; at: Token }
  | { kind: "repeat"; count: Expr; body: Stmt[]; at: Token };

const FORWARD = new Set(["np", "naprzod", "naprzód", "fd", "forward"]);
const RIGHT = new Set(["pw", "prawo", "rt", "right"]);
const REPEAT = new Set(["powtorz", "powtórz", "repeat"]);

export function parse(tokens: Token[]): Stmt[] {
  let pos = 0;
  const expr = (): Expr => {
    const t = tokens[pos++];
    return { kind: "num", value: t.value, at: t };
  };
  const block = (): Stmt[] => {
    pos++; // [
    const body: Stmt[] = [];
    while (tokens[pos].kind !== "rbr") body.push(stmt());
    pos++; // ]
    return body;
  };
  const stmt = (): Stmt => {
    const t = tokens[pos++];
    if (FORWARD.has(t.key)) return { kind: "move", sign: 1, arg: expr(), at: t };
    if (RIGHT.has(t.key)) return { kind: "turn", sign: 1, arg: expr(), at: t };
    if (REPEAT.has(t.key)) {
      const count = expr();
      return { kind: "repeat", count, body: block(), at: t };
    }
    throw new Error(`unknown ${t.text}`);
  };
  const program: Stmt[] = [];
  while (pos < tokens.length) program.push(stmt());
  return program;
}
