import type { Expr, Stmt } from "./parser";
import { Turtle } from "./turtle";
import type { Segment } from "./types";

export function execute(program: Stmt[]): Segment[] {
  const turtle = new Turtle();
  const segments: Segment[] = [];
  const evaluate = (e: Expr): number => e.value;
  const runBlock = (body: Stmt[]) => {
    for (const s of body) {
      if (s.kind === "move") {
        const to = turtle.moved(s.sign * evaluate(s.arg));
        segments.push({ from: turtle.position, to, color: "#16866a", width: 3 });
        turtle.position = to;
      } else if (s.kind === "turn") {
        turtle.turnRight(s.sign * evaluate(s.arg));
      } else {
        const n = evaluate(s.count);
        for (let i = 0; i < n; i++) runBlock(s.body);
      }
    }
  };
  runBlock(program);
  return segments;
}
EOF
