import type { Mode, RunResult } from "./types";

export type { LangError, Mode, RunResult, Segment, Vec3 } from "./types";

export function run(source: string, _mode: Mode): RunResult {
  const segments = execute(parse(lex(source)));
  return { segments, error: null };
}
