import type { Vec3 } from "./types";

/** cos/sin of an angle in degrees, exact at multiples of 90°. */
export function cosSin(degrees: number): [number, number] {
  const t = ((degrees % 360) + 360) % 360;
  if (t === 0) return [1, 0];
  if (t === 90) return [0, 1];
  if (t === 180) return [-1, 0];
  if (t === 270) return [0, -1];
  const r = (t * Math.PI) / 180;
  return [Math.cos(r), Math.sin(r)];
}

const add = (a: Vec3, b: Vec3, k: number): Vec3 => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k];
const mix = (a: Vec3, ka: number, b: Vec3, kb: number): Vec3 => [
  a[0] * ka + b[0] * kb,
  a[1] * ka + b[1] * kb,
  a[2] * ka + b[2] * kb,
];

export class Turtle {
  position: Vec3 = [0, 0, 0];
  heading: Vec3 = [0, 1, 0];
  right: Vec3 = [1, 0, 0];
  up: Vec3 = [0, 0, 1];

  moved(distance: number): Vec3 {
    return add(this.position, this.heading, distance);
  }

  /** Rotate the heading towards the right vector, around up. */
  turnRight(degrees: number): void {
    const [c, s] = cosSin(degrees);
    const h = this.heading;
    const r = this.right;
    this.heading = mix(h, c, r, s);
    this.right = mix(r, c, h, -s);
  }
}
