import { LogoError } from "./errors";
import { keywordOf, type Keyword } from "./keywords";
import type { Token } from "./lexer";
import { checkRepeatCount, checkWidth, evaluate, isLiteral } from "./values";

/** Every expression knows `first`, its leftmost token (an opening parenthesis included). */
export type Expr =
  | { kind: "num"; value: number; at: Token; first: Token }
  | { kind: "name"; name: string; at: Token; first: Token }
  | { kind: "repcount"; at: Token; first: Token }
  | { kind: "neg"; arg: Expr; at: Token; first: Token }
  | { kind: "bin"; op: "+" | "-" | "*" | "/"; left: Expr; right: Expr; at: Token; first: Token };

export type Comparison = "<" | ">" | "=" | "<=" | ">=" | "<>";
export interface Condition {
  left: Expr;
  op: Comparison;
  right: Expr;
  /** The condition is one argument: errors inside it point at its first token. */
  first: Token;
}

export type Stmt =
  | { kind: "move"; sign: 1 | -1; arg: Expr; at: Token }
  | { kind: "turn"; sign: 1 | -1; arg: Expr; at: Token }
  | { kind: "repeat"; count: Expr; body: Stmt[]; at: Token }
  | { kind: "pen"; down: boolean; at: Token }
  | { kind: "color"; color: string; at: Token }
  | { kind: "width"; arg: Expr; at: Token }
  | { kind: "let"; name: string; arg: Expr; at: Token }
  | { kind: "if"; cond: Condition; then: Stmt[]; otherwise: Stmt[] | null; at: Token }
  | { kind: "call"; name: string; args: Expr[]; at: Token };

export interface Procedure {
  name: string;
  params: string[];
  body: Stmt[];
  at: Token;
}

export interface Program {
  main: Stmt[];
  procedures: Map<string, Procedure>;
}

const SPACING_HINT = (op: string) =>
  ` Jeśli to miało być działanie, postaw odstęp po obu stronach znaku «${op}» albo po żadnej, na przykład «10 ${op} 5» lub «10${op}5».`;

const plural = (n: number, one: string, few: string, many: string) =>
  n === 1 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) ? few : many;

interface Header {
  name: Token;
  params: Token[];
  /** Index of the first body token. */
  bodyStart: number;
}

/** A `już` that ends a definition stands alone on its line. */
const isEnd = (t: Token | undefined) => !!t && t.kind === "word" && keywordOf(t.key) === "end";
const endsDefinition = (t: Token | undefined) => isEnd(t) && t!.lineFirst && t!.lineLast;
const isTo = (t: Token | undefined) => !!t && t.kind === "word" && keywordOf(t.key) === "to";

export function parse(tokens: Token[], source: string): Program {
  let pos = 0;

  // ---- Pre-scan: procedure headers and the names `niech` assigns in each scope. ----
  /** Read the header of the definition whose `oto` is at index i. Throws on malformed headers. */
  const readHeader = (i: number): Header => {
    const to = tokens[i];
    const sameLine = (t: Token | undefined) => !!t && t.line === to.line;
    const name = tokens[i + 1];
    if (!sameLine(name)) throw new LogoError(`Po «${to.text}» brakuje nazwy procedury w tym samym wierszu.`, to);
    if (name.kind !== "word") throw new LogoError(`Po «${to.text}» powinna stać nazwa procedury, a jest «${name.text}».`, name);
    if (keywordOf(name.key) !== undefined)
      throw new LogoError(`«${name.text}» to słowo języka, więc nie może być nazwą procedury.`, name);
    const params: Token[] = [];
    let j = i + 2;
    const addParam = (p: Token) => {
      if (p.kind === "word" && keywordOf(p.key) !== undefined)
        throw new LogoError(`«${p.text}» to słowo języka, więc nie może być nazwą parametru.`, p);
      if (params.some((q) => q.key === p.key)) throw new LogoError(`Parametr «${p.text}» powtarza się w nagłówku.`, p);
      params.push(p);
    };
    const next = tokens[j];
    const ma = next && sameLine(next) && next.kind === "word" && next.key === "ma" ? next : null;
    const maColon = ma && tokens[j + 1]?.kind === "colon" && tokens[j + 1].start === ma.end;
    const maGlued = ma && tokens[j + 1]?.kind === "colonword" && tokens[j + 1].start === ma.end;
    if (ma && (maColon || maGlued)) {
      j += maColon ? 2 : 1;
      for (;;) {
        const p = tokens[j];
        if (!sameLine(p)) throw new LogoError("Po «ma:» brakuje nazwy parametru.", tokens[j - 1]);
        if (p.kind !== "word" && p.kind !== "colonword")
          throw new LogoError(`Tu powinna stać nazwa parametru, a jest «${p.text}».`, p);
        addParam(p);
        j++;
        if (sameLine(tokens[j]) && tokens[j].kind === "comma") {
          j++;
          continue;
        }
        break;
      }
    } else {
      while (sameLine(tokens[j]) && tokens[j].kind === "colonword") addParam(tokens[j++]);
    }
    if (sameLine(tokens[j]))
