  };

  const headers = new Map<string, { header: Header; to: Token }>();
  const globals = new Set<string>();
  const localsOf = new Map<string, Set<string>>();
  {
    let scope: Set<string> = globals;
    let inside = false;
    for (let i = 0; i < tokens.length; i++) {
      const t = tokens[i];
      if (!inside && isTo(t) && t.lineFirst) {
        let header: Header | null = null;
        try {
          header = readHeader(i);
        } catch {
          // Reported properly by the main parse.
        }
        if (header) {
          if (!headers.has(header.name.key)) headers.set(header.name.key, { header, to: t });
          scope = localsOf.get(header.name.key) ?? new Set();
          localsOf.set(header.name.key, scope);
          inside = true;
          i = header.bodyStart - 1;
        }
