  // ---- Main parse. ----
  interface Scope {
    procedure: Procedure | null;
    params: Set<string>;
    locals: Set<string>;
  }
  const topScope: Scope = { procedure: null, params: new Set(), locals: new Set() };
  let scope = topScope;
  /** How many repeat bodies enclose the code being parsed, lexically, in the current scope. */
  let repeatDepth = 0;
  /** How many bracketed bodies enclose the code being parsed. */
  let bracketDepth = 0;

  const kw = (t: Token | undefined): Keyword | undefined => (t && t.kind === "word" ? keywordOf(t.key) : undefined);
