  /** A binary operator only when spaced on both sides or on neither. */
  const binaryAt = (ops: string): boolean => {
    const t = tokens[pos];
    return !!t && t.kind === "op" && ops.includes(t.text) && t.spaceBefore === t.spaceAfter;
  };
  /** The value `owner` needs is missing: report at the token found instead, or at `owner` at the end. */
  const missingValue = (owner: Token): never => {
    const found = tokens[pos];
    if (!found) throw new LogoError(`Po «${owner.text}» brakuje wartości: liczby, nazwy albo wyrażenia.`, owner);
    throw new LogoError(`Po «${owner.text}» powinna stać wartość, a jest «${found.text}».`, found);
  };
  const primary = (owner: Token): Expr => {
    const t = tokens[pos];
    if (!t || !startsValue(t)) return missingValue(owner);
    pos++;
    if (t.kind === "op") {
      const arg = primary(t);
      return t.text === "-" ? { kind: "neg", arg, at: t, first: t } : { ...arg, first: t };
    }
    if (t.kind === "lpar") {
      const inner = exprOf(t);
      if (tokens[pos]?.kind !== "rpar") throw new LogoError("Nawias «(» nie został zamknięty: brakuje «)».", t);
      pos++;
      return { ...inner, first: t };
    }
    if (isRepcount(t)) {
      if (repeatDepth === 0)
        throw new LogoError(`«${t.text}» działa tylko wewnątrz nawiasów «powtórz … [ ]»: to numer bieżącego powtórzenia.`, t);
      return { kind: "repcount", at: t, first: t };
    }
    if (isName(t)) {
      if (!visible(t.key)) {
        const hint = headers.has(t.key)
          ? ` «${t.text}» to procedura: wywołuje się ją jako polecenie, nie jako wartość.`
          : " Wartością może być liczba, parametr procedury albo zmienna nadana przez «niech».";
