    let left = primary(owner);
    while (binaryAt("*/")) {
      const op = tokens[pos++];
      left = { kind: "bin", op: op.text as "*" | "/", left, right: primary(op), at: op, first: left.first };
    }
    return left;
  };
  const exprOf = (owner: Token): Expr => {
    let left = term(owner);
    while (binaryAt("+-")) {
      const op = tokens[pos++];
      left = { kind: "bin", op: op.text as "+" | "-", left, right: term(op), at: op, first: left.first };
    }
    return left;
  };

