import { LogoError } from "./errors";
import { keywordOf, type Keyword } from "./keywords";
import type { Token } from "./lexer";
import { checkRepeatCount, checkWidth, evaluate, isLiteral } from "./values";

/** Every expression knows `first`, its leftmost token (an opening parenthesis included). */
export type Expr =
  | { kind: "num"; value: number; at: Token; first: Token }
  | { kind: "name"; name: string; at: Token; first: Token }
