  | { kind: "bin"; op: "+" | "-" | "*" | "/"; left: Expr; right: Expr; at: Token; first: Token };

export type Comparison = "<" | ">" | "=" | "<=" | ">=" | "<>";
export interface Condition {
  left: Expr;
  op: Comparison;
  right: Expr;
  /** The condition is one argument: errors inside it point at its first token. */
  first: Token;
}

export type Stmt =
  | { kind: "move"; sign: 1 | -1; arg: Expr; at: Token }
  | { kind: "turn"; sign: 1 | -1; arg: Expr; at: Token }
  | { kind: "repeat"; count: Expr; body: Stmt[]; at: Token }
  | { kind: "pen"; down: boolean; at: Token }
  | { kind: "color"; color: string; at: Token }
  | { kind: "width"; arg: Expr; at: Token }
  | { kind: "let"; name: string; arg: Expr; at: Token }
  | { kind: "if"; cond: Condition; then: Stmt[]; otherwise: Stmt[] | null; at: Token }
  | { kind: "call"; name: string; args: Expr[]; at: Token };

export interface Procedure {
  name: string;
  params: string[];
  body: Stmt[];
  at: Token;
}

export interface Program {
  main: Stmt[];
  procedures: Map<string, Procedure>;
}

