  ` Jeśli to miało być działanie, postaw odstęp po obu stronach znaku «${op}» albo po żadnej, na przykład «10 ${op} 5» lub «10${op}5».`;

const plural = (n: number, one: string, few: string, many: string) =>
  n === 1 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) ? few : many;

interface Header {
  name: Token;
  params: Token[];
  /** Index of the first body token. */
  bodyStart: number;
}

/** A `już` that ends a definition stands alone on its line. */
const isEnd = (t: Token | undefined) => !!t && t.kind === "word" && keywordOf(t.key) === "end";
const endsDefinition = (t: Token | undefined) => isEnd(t) && t!.lineFirst && t!.lineLast;
const isTo = (t: Token | undefined) => !!t && t.kind === "word" && keywordOf(t.key) === "to";

