  };

  const procedures = new Map<string, Procedure>();
  const definition = () => {
    const to = tokens[pos];
    if (!to.lineFirst) throw new LogoError(`Definicja procedury musi zaczynać się od «${to.text}» na początku wiersza.`, to);
