    if (earlier)
      throw new LogoError(`Procedura «${name.text}» jest już zdefiniowana w wierszu ${earlier.at.line}. Nazwa może być użyta tylko raz.`, name);
    const proc: Procedure = { name: name.key, params: header.params.map((p) => p.key), body: [], at: name };
    procedures.set(name.key, proc);
    pos = header.bodyStart;
    scope = { procedure: proc, params: new Set(proc.params), locals: localsOf.get(name.key) ?? new Set() };
    repeatDepth = 0;
    for (;;) {
      const t = tokens[pos];
      if (!t)
        throw new LogoError(`Procedura «${name.text}» nie ma zakończenia: dopisz «już» w osobnym wierszu.`, to);
      if (isEnd(t)) {
        if (!endsDefinition(t)) throw new LogoError(`«${t.text}» musi stać sam w osobnym wierszu.`, t);
