import { LogoError } from "./errors";
import type { Expr, Program, Stmt } from "./parser";
import { Turtle } from "./turtle";
import type { RunResult, Segment } from "./types";
import { checkRepeatCount, checkWidth, evaluate } from "./values";

interface Frame {
  /** Parameters and `niech` locals of a procedure call; null at top level. */
  locals: Map<string, number> | null;
  /** Iteration numbers of the repeats active in this frame, innermost last. */
  iterations: number[];
}

export function execute(program: Program): RunResult {
  const turtle = new Turtle();
  const segments: Segment[] = [];
  const pen = { down: true, color: "#16866a", width: 3 };
  const globals = new Map<string, number>();
  let frame: Frame = { locals: null, iterations: [] };

  const lookup = (n: { name: string }) => frame.locals?.get(n.name) ?? globals.get(n.name);
  const repcount = () => frame.iterations[frame.iterations.length - 1];
  const value = (arg: Expr, argStart: Expr = arg) => evaluate(arg, argStart, lookup, repcount);

  const runBlock = (body: Stmt[]) => {
    for (const s of body) {
      switch (s.kind) {
        case "move": {
          const to = turtle.moved(s.sign * value(s.arg));
          const changed = to.some((v, i) => v !== turtle.position[i]);
          if (pen.down && changed) segments.push({ from: turtle.position, to, color: pen.color, width: pen.width });
          turtle.position = to;
          break;
        }
        case "turn":
          turtle.turnRight(s.sign * value(s.arg));
          break;
        case "pen":
          pen.down = s.down;
          break;
        case "color":
          pen.color = s.color;
          break;
        case "width":
          pen.width = checkWidth(value(s.arg), s.arg);
          break;
        case "let":
          (frame.locals ?? globals).set(s.name, value(s.arg));
          break;
        case "if": {
          const { left, op, right } = s.cond;
          const argStart = { ...left, first: s.cond.first };
          const a = value(left, argStart);
          const b = value(right, argStart);
          const holds =
            op === "<" ? a < b : op === ">" ? a > b : op === "=" ? a === b : op === "<=" ? a <= b : op === ">=" ? a >= b : a !== b;
          const body = holds ? s.then : s.otherwise;
          if (body) runBlock(body);
          break;
        }
        case "repeat": {
          const n = checkRepeatCount(value(s.count), s.count);
          frame.iterations.push(0);
          for (let i = 1; i <= n; i++) {
            frame.iterations[frame.iterations.length - 1] = i;
            runBlock(s.body);
          }
          frame.iterations.pop();
          break;
        }
        case "call": {
          const proc = program.procedures.get(s.name)!;
          const args = s.args.map((a) => value(a));
          const caller = frame;
          frame = { locals: new Map(proc.params.map((p, i) => [p, args[i]])), iterations: [] };
          try {
            runBlock(proc.body);
          } finally {
            frame = caller;
          }
          break;
        }
      }
    }
  };
  try {
    runBlock(program.main);
  } catch (e) {
    if (e instanceof LogoError) return { segments, error: e.toJSON() };
    throw e;
  }
  return { segments, error: null };
}
