import { LogoError, type Position } from "./errors";
import { LIMITS } from "./limits";
import type { Expr, Program, Stmt } from "./parser";
import { Turtle } from "./turtle";
import type { LangError, RunResult, Segment, Vec3 } from "./types";
import { checkRepeatCount, checkWidth, evaluate } from "./values";

/** Where the turtle is and what its pen does. */
export interface TurtleState {
  position: Vec3;
  heading: Vec3;
  right: Vec3;
  up: Vec3;
  penDown: boolean;
  color: string;
  width: number;
}

/** A command's place in the source: 1-based line and column, length in characters. */
export interface Span {
  line: number;
  column: number;
  length: number;
}

interface Frame {
  /** Parameters and `niech` locals of a procedure call; null at top level. */
  locals: Map<string, number> | null;
  /** Iteration numbers of the repeats active in this frame, innermost last. */
  iterations: number[];
}

/** Thrown by `stop`; caught by the enclosing call, or by the program at top level. */
class Stop {}

const spanOf = (s: Stmt): Span => ({ line: s.at.line, column: s.at.column, length: s.at.end - s.at.start });

/**
 * A program being executed one command at a time. `step()` runs exactly one
 * command (plus the bookkeeping after it) and stops before the next one.
 */
export class Execution {
  readonly segments: Segment[] = [];
  error: LangError | null = null;
  done = false;
  /** The command that ran last. */
  current: Span | null = null;
  /** The command that runs next. */
  next: Span | null = null;
  operations = 0;

  private readonly turtle = new Turtle();
  private readonly pen = { down: true, color: "#16866a", width: 3 };
  private readonly globals = new Map<string, number>();
  private frame: Frame = { locals: null, iterations: [] };
  private activeFrames = 0;
  private readonly steps: Generator<Stmt, void, void>;

  constructor(private readonly program: Program) {
    this.steps = this.main();
    this.advance();
  }

  get turtleState(): TurtleState {
    const t = this.turtle;
    return {
      position: t.position,
      heading: t.heading,
      right: t.right,
      up: t.up,
      penDown: this.pen.down,
      color: this.pen.color,
      width: this.pen.width,
    };
  }

  /** Execute the next command. Returns false once the program has finished or failed. */
  step(): boolean {
    if (this.done) return false;
    this.current = this.next;
    this.advance();
    return !this.done;
  }

  runToEnd(): RunResult {
    while (this.step());
    return { segments: this.segments, error: this.error };
  }

  private advance(): void {
    try {
      const r = this.steps.next();
      if (r.done) {
        this.done = true;
        this.next = null;
      } else {
        this.next = spanOf(r.value);
      }
    } catch (e) {
      if (!(e instanceof LogoError)) throw e;
      this.error = e.toJSON();
      this.done = true;
      this.next = null;
    }
  }

  private *main(): Generator<Stmt, void, void> {
    try {
      yield* this.block(this.program.main);
    } catch (e) {
      if (!(e instanceof Stop)) throw e;
    }
  }

  /** Count one executed operation, attributed to `at`. */
  private tick(at: Position): void {
    if (++this.operations > LIMITS.operations)
      throw new LogoError(
        "Program wykonał już 10 000 operacji i został zatrzymany. Czy któraś pętla albo rekurencja nie ma końca?",
        at,
      );
  }

  /** Enter a procedure-call or repeat frame, attributed to `at`. */
  private enterFrame(at: Position): void {
    if (++this.activeFrames > LIMITS.frames)
      throw new LogoError(
        "Za głęboko: naraz może działać najwyżej 32 wywołania procedur i powtórzenia. Czy rekurencja ma warunek z «stop»?",
        at,
      );
  }

  private value(arg: Expr, argStart: Expr = arg): number {
    const frame = this.frame;
    return evaluate(
      arg,
      argStart,
      (n) => frame.locals?.get(n.name) ?? this.globals.get(n.name),
      () => frame.iterations[frame.iterations.length - 1],
    );
  }

  private moveTo(to: Vec3, at: Position): void {
    if (to.some((v) => Math.abs(v) > LIMITS.coordinate))
      throw new LogoError(
        "Żółw wyszedłby poza obszar rysowania: każda współrzędna musi mieścić się między −100 000 a 100 000.",
        at,
      );
    const from = this.turtle.position;
    const changed = to.some((v, i) => v !== from[i]);
    if (this.pen.down && changed) {
      // The brief's segment limit. With the operation limit in force it cannot be reached
      // (every kept segment costs at least one operation), but it stays as specified.
      if (this.segments.length >= LIMITS.segments)
        throw new LogoError("Za dużo odcinków: rysunek może mieć najwyżej 10 000 odcinków.", at);
      this.segments.push({ from, to, color: this.pen.color, width: this.pen.width });
    }
    this.turtle.position = to;
  }

  private *block(body: Stmt[]): Generator<Stmt, void, void> {
    for (const s of body) {
      yield s;
      this.tick(s.at);
      yield* this.statement(s);
    }
  }

  private *statement(s: Stmt): Generator<Stmt, void, void> {
    const { turtle, pen } = this;
    switch (s.kind) {
      case "move":
        this.moveTo(turtle.moved(s.sign * this.value(s.arg)), s.at);
        return;
      case "home":
        this.moveTo([0, 0, 0], s.at);
        turtle.resetOrientation();
        return;
      case "clear":
        this.segments.length = 0;
        return;
      case "turn":
        turtle.turnRight(s.sign * this.value(s.arg));
        return;
      case "pitch":
        turtle.pitchUp(s.sign * this.value(s.arg));
        return;
      case "roll":
        turtle.rollRight(s.sign * this.value(s.arg));
        return;
      case "pen":
        pen.down = s.down;
        return;
      case "color":
        pen.color = s.color;
        return;
      case "width":
        pen.width = checkWidth(this.value(s.arg), s.arg);
        return;
      case "let":
        (this.frame.locals ?? this.globals).set(s.name, this.value(s.arg));
        return;
      case "stop":
        throw new Stop();
      case "if": {
        const { left, op, right } = s.cond;
        const argStart = { ...left, first: s.cond.first };
        const a = this.value(left, argStart);
        const b = this.value(right, argStart);
        const holds =
          op === "<" ? a < b : op === ">" ? a > b : op === "=" ? a === b : op === "<=" ? a <= b : op === ">=" ? a >= b : a !== b;
        const body = holds ? s.then : s.otherwise;
        if (body) {
          yield* this.block(body);
          this.tick(s.at);
        }
        return;
      }
      case "repeat": {
        const n = checkRepeatCount(this.value(s.count), s.count);
        this.enterFrame(s.at);
        const iterations = this.frame.iterations;
        iterations.push(0);
        try {
          for (let i = 1; i <= n; i++) {
            iterations[iterations.length - 1] = i;
            yield* this.block(s.body);
            this.tick(s.at);
          }
        } finally {
          iterations.pop();
          this.activeFrames--;
        }
        return;
      }
      case "call": {
        const proc = this.program.procedures.get(s.name)!;
        const args = s.args.map((a) => this.value(a));
        this.enterFrame(s.at);
        const caller = this.frame;
        this.frame = { locals: new Map(proc.params.map((p, i) => [p, args[i]])), iterations: [] };
        try {
          yield* this.block(proc.body);
        } catch (e) {
          if (!(e instanceof Stop)) throw e;
        } finally {
          this.frame = caller;
          this.activeFrames--;
        }
        this.tick(s.at);
        return;
      }
    }
  }
}

/** An execution that failed before it started (a parse-time error). */
export function failedExecution(error: LangError): Execution {
  const ex = new Execution({ main: [], procedures: new Map() });
  ex.error = error;
  return ex;
}
