      case "clear":
        this.segments.length = 0;
        return;
      case "turn":
        turtle.turnRight(s.sign * this.value(s.arg));
        return;
      case "pitch":
        turtle.pitchUp(s.sign * this.value(s.arg));
        return;
      case "roll":
        turtle.rollRight(s.sign * this.value(s.arg));
        return;
      case "pen":
        pen.down = s.down;
        return;
      case "color":
        pen.color = s.color;
        return;
      case "width":
        pen.width = checkWidth(this.value(s.arg), s.arg);
        return;
      case "let":
        (this.frame.locals ?? this.globals).set(s.name, this.value(s.arg));
        return;
      case "stop":
        throw new Stop();
      case "if": {
        const { left, op, right } = s.cond;
        const argStart = { ...left, first: s.cond.first };
        const a = this.value(left, argStart);
        const b = this.value(right, argStart);
        const holds =
          op === "<" ? a < b : op === ">" ? a > b : op === "=" ? a === b : op === "<=" ? a <= b : op === ">=" ? a >= b : a !== b;
        const body = holds ? s.then : s.otherwise;
        if (body) {
          yield* this.block(body);
          this.tick(s.at);
        }
        return;
      }
      case "repeat": {
        const n = checkRepeatCount(this.value(s.count), s.count);
        this.enterFrame(s.at);
        const iterations = this.frame.iterations;
        iterations.push(0);
        try {
          for (let i = 1; i <= n; i++) {
            iterations[iterations.length - 1] = i;
            yield* this.block(s.body);
            this.tick(s.at);
          }
        } finally {
          iterations.pop();
          this.activeFrames--;
        }
        return;
      }
      case "call": {
        const proc = this.program.procedures.get(s.name)!;
        const args = s.args.map((a) => this.value(a));
        this.enterFrame(s.at);
        const caller = this.frame;
        this.frame = { locals: new Map(proc.params.map((p, i) => [p, args[i]])), iterations: [] };
        try {
          yield* this.block(proc.body);
        } catch (e) {
          if (!(e instanceof Stop)) throw e;
        } finally {
          this.frame = caller;
          this.activeFrames--;
        }
        this.tick(s.at);
        return;
      }
    }
  }
}

/** An execution that failed before it started (a parse-time error). */
export function failedExecution(error: LangError): Execution {
  const ex = new Execution({ main: [], procedures: new Map() });
  ex.error = error;
  return ex;
}
