import { LogoError } from "./errors";
import { Execution, failedExecution } from "./exec";
import { lex } from "./lexer";
import { parse } from "./parser";
import type { Mode, RunResult } from "./types";

export type { Execution, Span, TurtleState } from "./exec";
export type { LangError, Mode, RunResult, Segment, Vec3 } from "./types";

/** Validate the whole program, then return an execution ready to step. */
export function start(source: string, mode: Mode): Execution {
  try {
    return new Execution(parse(lex(source), source, mode));
  } catch (e) {
    if (e instanceof LogoError) return failedExecution(e.toJSON());
    throw e;
  }
}

/** Interpret a program to the end: the drawn segments and the first error, if any. */
export function run(source: string, mode: Mode): RunResult {
  return start(source, mode).runToEnd();
}
