  forward: "kw-move",
  back: "kw-move",
  home: "kw-move",
  right: "kw-turn",
  left: "kw-turn",
  pitchup: "kw-turn",
  pitchdown: "kw-turn",
  rollright: "kw-turn",
  rollleft: "kw-turn",
  penup: "kw-pen",
  pendown: "kw-pen",
  color: "kw-pen",
  width: "kw-pen",
  clear: "kw-pen",
  repeat: "kw-control",
  if: "kw-control",
  ifelse: "kw-control",
  stop: "kw-control",
  repcount: "kw-control",
  to: "kw-define",
  end: "kw-define",
  let: "kw-define",
};

const WORD = /[\p{L}_][\p{L}\p{N}_]*/uy;
const NUMBER = /(\d+(\.\d+)?|\.\d+)/y;

/**
 * Tokenise for highlighting. Never throws: malformed input becomes `invalid`
 * tokens, so the editor stays coloured while the learner types.
 */
export function highlightTokens(source: string): HighlightToken[] {
  const out: HighlightToken[] = [];
  const procedures = new Set<string>();
  for (const m of source.matchAll(/(?:^|\n)[ \t]*(?:oto|to)[ \t]+([\p{L}_][\p{L}\p{N}_]*)/giu)) procedures.add(m[1].toLowerCase());
  let i = 0;
  let afterTo = false;
  while (i < source.length) {
    const c = source[i];
    if (c === " " || c === "\t" || c === "\n" || c === "\r") {
      i++;
      continue;
    }
    const start = i;
    const push = (cls: TokenClass, end: number, color?: string) => {
      out.push(color ? { from: start, to: end, cls, color } : { from: start, to: end, cls });
      i = end;
    };
    if (c === ";") {
      const nl = source.indexOf("\n", i);
      push("comment", nl === -1 ? source.length : nl);
      continue;
    }
    if (c === '"') {
      let end = i + 1;
      while (end < source.length && source[end] !== '"' && source[end] !== "\n") end++;
      const closed = source[end] === '"';
      if (closed) end++;
      const text = source.slice(start, end);
      const ok = /^"#[0-9a-f]{6}"$/i.test(text);
      push(ok ? "str" : "invalid", end, ok ? text.slice(1, -1).toLowerCase() : undefined);
      continue;
    }
    NUMBER.lastIndex = i;
    const num = NUMBER.exec(source);
    if (num) {
      let end = i + num[0].length;
      const glued = /[\p{L}\p{N}_.]/u.test(source[end] ?? "");
      if (glued) while (end < source.length && /[\p{L}\p{N}_.]/u.test(source[end])) end++;
      push(glued ? "invalid" : "num", end);
      afterTo = false;
      continue;
    }
    if (c === ":" && /[\p{L}_]/u.test(source[i + 1] ?? "")) {
      WORD.lastIndex = i + 1;
      const w = WORD.exec(source)!;
      push("name", i + 1 + w[0].length);
      continue;
    }
    WORD.lastIndex = i;
    const word = WORD.exec(source);
    if (word) {
      const key = word[0].toLowerCase();
      const kw = keywordOf(key);
      const end = i + word[0].length;
      if (kw) push(FAMILY[kw], end);
      else if (afterTo || procedures.has(key)) push("proc", end);
      else if (key === "ma" && source[end] === ":") push("kw-define", end + 1);
      else push("name", end);
      afterTo = kw === "to";
      continue;
    }
    afterTo = false;
    if (c === "[" || c === "]") push("bracket", i + 1);
    else if (c === "(" || c === ")") push("paren", i + 1);
    else if ("+-*/<>=,".includes(c)) push("op", i + (source.startsWith("<=", i) || source.startsWith(">=", i) || source.startsWith("<>", i) ? 2 : 1));
    else push("invalid", i + 1);
  }
  return out;
}
