import { defaultKeymap, history, historyKeymap, insertNewlineAndIndent } from "@codemirror/commands";
import { bracketMatching, indentService, indentUnit } from "@codemirror/language";
import { EditorState, RangeSetBuilder, StateEffect, StateField, type Extension } from "@codemirror/state";
import {
  Decoration,
  EditorView,
  ViewPlugin,
  WidgetType,
  drawSelection,
  highlightActiveLine,
  highlightActiveLineGutter,
  keymap,
  lineNumbers,
  placeholder,
  type DecorationSet,
  type ViewUpdate,
} from "@codemirror/view";
import { highlightTokens } from "../lang/highlight";

export interface EditorMark {
  line: number;
  column: number;
  /** Characters to mark; at least one. */
  length?: number;
  message?: string;
}

/** The editor as the studio sees it. */
export interface CodeEditor {
  getText(): string;
  /** Replace the whole text as one undoable change (as if pasted). */
  setText(text: string): void;
  setError(mark: EditorMark | null): void;
  setCurrent(mark: EditorMark | null): void;
  focus(): void;
  /** Move the caret to a 1-based position and reveal it. */
  reveal(line: number, column: number): void;
  destroy(): void;
}

// ---- Highlighting: re-tokenise the whole document (≤ 50 000 chars) on change. ----
const tokenMarks = new Map<string, Decoration>();
const markFor = (cls: string) => {
  let m = tokenMarks.get(cls);
  if (!m) tokenMarks.set(cls, (m = Decoration.mark({ class: `tok-${cls}` })));
  return m;
};

function buildHighlights(view: EditorView): DecorationSet {
  const builder = new RangeSetBuilder<Decoration>();
  for (const t of highlightTokens(view.state.doc.toString())) {
    if (t.cls === "str" && t.color) {
      builder.add(t.from, t.to, Decoration.mark({ class: "tok-str", attributes: { style: `--swatch:${t.color}` } }));
    } else builder.add(t.from, t.to, markFor(t.cls));
  }
  return builder.finish();
}

const highlighter = ViewPlugin.fromClass(
  class {
    decorations: DecorationSet;
    constructor(view: EditorView) {
      this.decorations = buildHighlights(view);
    }
    update(u: ViewUpdate) {
      if (u.docChanged) this.decorations = buildHighlights(u.view);
    }
  },
  { decorations: (v) => v.decorations },
);

// ---- Error and execution markers. ----
class MessageWidget extends WidgetType {
  constructor(
    readonly message: string,
    readonly column: number,
  ) {
    super();
  }
  eq(other: MessageWidget) {
    return other.message === this.message && other.column === this.column;
  }
  toDOM() {
    const el = document.createElement("div");
    el.className = "cm-logo-message";
    el.setAttribute("role", "note");
    el.style.setProperty("--col", String(this.column - 1));
    const text = document.createElement("span");
    text.textContent = this.message;
    el.append(text);
    return el;
  }
  ignoreEvent() {
    return false;
  }
}

const setErrorEffect = StateEffect.define<EditorMark | null>();
const setCurrentEffect = StateEffect.define<EditorMark | null>();

/** Clamp a 1-based mark to the document and give its character range. */
function rangeOf(state: EditorState, m: EditorMark) {
  const line = state.doc.line(Math.max(1, Math.min(state.doc.lines, m.line)));
  const from = Math.min(line.to, line.from + Math.max(0, m.column - 1));
  const to = Math.min(line.to, from + Math.max(1, m.length ?? 1));
  return { line, from, to };
}

function markerField(effect: typeof setErrorEffect, lineClass: string, tokenClass: string, withMessage: boolean) {
  return StateField.define<{ mark: EditorMark | null; deco: DecorationSet }>({
    create: () => ({ mark: null, deco: Decoration.none }),
    update(value, tr) {
      let mark = value.mark;
      for (const e of tr.effects) if (e.is(effect)) mark = e.value;
      // An edit makes the marker stale: drop it rather than point at the wrong code.
      if (tr.docChanged && mark === value.mark) mark = null;
      if (mark === value.mark && !tr.docChanged) return value;
      if (!mark) return { mark: null, deco: Decoration.none };
      const { line, from, to } = rangeOf(tr.state, mark);
      const ranges = [Decoration.line({ class: lineClass }).range(line.from)];
      if (to > from) ranges.push(Decoration.mark({ class: tokenClass }).range(from, to));
      if (withMessage && mark.message)
        ranges.push(Decoration.widget({ widget: new MessageWidget(mark.message, from - line.from + 1), block: true, side: 1 }).range(line.to));
      return { mark, deco: Decoration.set(ranges, true) };
    },
    provide: (f) => EditorView.decorations.from(f, (v) => v.deco),
  });
}

const errorField = markerField(setErrorEffect, "cm-logo-error-line", "cm-logo-error", true);
const currentField = markerField(setCurrentEffect, "cm-logo-exec-line", "cm-logo-exec", false);

/** Indent by bracket depth: two spaces per open `[` before the line. */
const bracketIndent = indentService.of((ctx, pos) => {
  const before = ctx.state.doc.sliceString(0, pos);
  let depth = 0;
  for (const m of before.replace(/;[^\n]*/g, "").matchAll(/[[\]]/g)) depth += m[0] === "[" ? 1 : -1;
  const lineText = ctx.lineAt(pos, 1).text.trimStart();
  if (lineText.startsWith("]")) depth--;
  return Math.max(0, depth) * 2;
});

export interface EditorOptions {
  doc: string;
  onChange: (text: string) => void;
  label: string;
  describedBy?: string;
  extraKeys?: Extension;
}

export function createEditor(parent: HTMLElement, options: EditorOptions): CodeEditor {
  let silent = false;
  const view = new EditorView({
    parent,
    state: EditorState.create({
      doc: options.doc,
      extensions: [
        options.extraKeys ?? [],
        lineNumbers(),
        highlightActiveLineGutter(),
        highlightActiveLine(),
        history(),
        drawSelection(),
        bracketMatching(),
        indentUnit.of("  "),
        bracketIndent,
        keymap.of([{ key: "Enter", run: insertNewlineAndIndent }, ...defaultKeymap, ...historyKeymap]),
        highlighter,
        errorField,
        currentField,
        placeholder("Napisz polecenie, na przykład: np 100"),
        EditorView.lineWrapping,
        EditorView.contentAttributes.of({
          "aria-label": options.label,
          ...(options.describedBy ? { "aria-describedby": options.describedBy } : {}),
          spellcheck: "false",
          autocapitalize: "off",
          autocorrect: "off",
          translate: "no",
        }),
        EditorView.updateListener.of((u) => {
          if (u.docChanged && !silent) options.onChange(u.state.doc.toString());
        }),
      ],
    }),
  });

  return {
    getText: () => view.state.doc.toString(),
    setText(text) {
      if (text === view.state.doc.toString()) return;
      silent = true;
      view.dispatch({
        changes: { from: 0, to: view.state.doc.length, insert: text },
        selection: { anchor: 0 },
        userEvent: "input.paste",
        scrollIntoView: true,
      });
      silent = false;
    },
    setError(mark) {
      view.dispatch({ effects: setErrorEffect.of(mark) });
    },
    setCurrent(mark) {
      const effects = [setCurrentEffect.of(mark)];
      if (mark) {
        const { from } = rangeOf(view.state, mark);
        effects.push(EditorView.scrollIntoView(from, { y: "nearest" }) as never);
      }
      view.dispatch({ effects });
    },
    focus: () => view.focus(),
    reveal(line, column) {
      const { from } = rangeOf(view.state, { line, column });
      view.dispatch({ selection: { anchor: from }, scrollIntoView: true });
      view.focus();
    },
    destroy: () => view.destroy(),
  };
}
