/** Everything a view draws. */
export interface Scene {
  segments: readonly Segment[];
  turtle: TurtleState | null;
  /** The turtle a moment ago, while the latest command is animating. */
  tween: { from: TurtleState; t: number; drewSegment: boolean } | null;
  /** A challenge's target drawing, shown as dashed fold lines. */
  ghost: readonly Segment[];
}

export const EMPTY_SCENE: Scene = { segments: [], turtle: null, tween: null, ghost: [] };

/** Colours views read from the page's design tokens. */
export interface Palette {
  sheet: string;
  ink: string;
  rule: string;
  ruleStrong: string;
  ghost: string;
  axisX: string;
  axisY: string;
  axisZ: string;
}

export function readPalette(el: Element = document.documentElement): Palette {
  const cs = getComputedStyle(el);
  const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    sheet: v("--sheet", "#fbfcfa"),
    ink: v("--sheet-ink", "#17221e"),
    rule: v("--sheet-rule", "#dfe4df"),
    ruleStrong: v("--sheet-rule-strong", "#b9c2bc"),
    ghost: v("--sheet-ghost", "#7d8a84"),
    axisX: v("--axis-x", "#c1763d"),
    axisY: v("--axis-y", "#16866a"),
    axisZ: v("--axis-z", "#2b6fb3"),
  };
}

export const lerp = (a: Vec3, b: Vec3, t: number): Vec3 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

/** Rotate unit vectors from a to b by fraction t (normalised linear blend is enough for one command). */
export function blendDir(a: Vec3, b: Vec3, t: number): Vec3 {
  const v = lerp(a, b, t);
  const n = Math.hypot(v[0], v[1], v[2]);
  return n < 1e-9 ? (t < 0.5 ? a : b) : [v[0] / n, v[1] / n, v[2] / n];
}

/** The scene as it looks mid-animation: the last segment partly drawn, the turtle between states. */
export function animatedScene(scene: Scene): { segments: readonly Segment[]; turtle: TurtleState | null } {
  const { tween, turtle } = scene;
  if (!tween || !turtle || tween.t >= 1) return { segments: scene.segments, turtle };
  const t = Math.max(0, tween.t);
  const pos = lerp(tween.from.position, turtle.position, t);
  const shown: TurtleState = {
    ...turtle,
    position: pos,
    heading: blendDir(tween.from.heading, turtle.heading, t),
    right: blendDir(tween.from.right, turtle.right, t),
    up: blendDir(tween.from.up, turtle.up, t),
  };
  if (!tween.drewSegment || scene.segments.length === 0) return { segments: scene.segments, turtle: shown };
  const last = scene.segments[scene.segments.length - 1];
  const segments = scene.segments.slice(0, -1);
  if (t > 0) segments.push({ ...last, to: lerp(last.from, last.to, t) });
  return { segments, turtle: shown };
}

/** Bounding box of segments (and optional extra points). */
export function bounds(segments: readonly Segment[], extra: Vec3[] = []): { min: Vec3; max: Vec3 } | null {
  const pts: Vec3[] = [...extra];
  for (const s of segments) pts.push(s.from, s.to);
  if (pts.length === 0) return null;
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (const p of pts)
    for (let i = 0; i < 3; i++) {
      min[i] = Math.min(min[i], p[i]);
      max[i] = Math.max(max[i], p[i]);
    }
  return { min, max };
}
