import type { Segment, TurtleState, Vec3 } from "../lang";
import { animatedScene, bounds, EMPTY_SCENE, readPalette, type Palette, type Scene } from "./scene";
import { clampStep, ONE_TO_ONE, scaleLabel, scaleValue, stepAtMost } from "./scale";

export type Projection = "top" | "iso";

const S2 = Math.SQRT2;
const S6 = Math.sqrt(6);
/** World → plane coordinates (y up) for a projection. */
export function project(p: Vec3, projection: Projection): [number, number] {
  if (projection === "top") return [p[0], p[1]];
  return [(p[0] + p[1]) / S2, (-p[0] + p[1] + 2 * p[2]) / S6];
}

const GRID_STEPS = [1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000];

export interface View2DOptions {
  projection: Projection;
  /** Called when the scale or framing changes (for the sheet imprint). */
  onViewChange?: () => void;
  label?: string;
}

/** Draw a scene onto a 2D context with a given plane→screen mapping. */
function paint(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  scene: Scene,
  palette: Palette,
  projection: Projection,
  scale: number,
  center: [number, number],
  options: { grid: boolean; marks: boolean },
) {
  const toScreen = (p: Vec3): [number, number] => {
    const [x, y] = project(p, projection);
    return [w / 2 + (x - center[0]) * scale, h / 2 - (y - center[1]) * scale];
  };
  ctx.fillStyle = palette.sheet;
  ctx.fillRect(0, 0, w, h);

  if (options.grid) drawGrid(ctx, w, h, palette, projection, scale, center, toScreen);

  // Challenge target: dashed fold lines under the learner's drawing.
  if (scene.ghost.length) {
    ctx.save();
    ctx.strokeStyle = palette.ghost;
    ctx.lineWidth = 1.5;
    ctx.setLineDash([7, 5]);
    ctx.lineCap = "butt";
    ctx.beginPath();
    for (const s of scene.ghost) {
      const a = toScreen(s.from);
      const b = toScreen(s.to);
      ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
    }
    ctx.stroke();
    ctx.restore();
  }

  if (options.marks) drawRegistrationMark(ctx, toScreen([0, 0, 0]), palette);

  const { segments, turtle } = animatedScene(scene);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  // Batch consecutive segments that share colour and width into one path.
  let i = 0;
  while (i < segments.length) {
    const { color, width } = segments[i];
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.beginPath();
    let last: [number, number] | null = null;
    while (i < segments.length && segments[i].color === color && segments[i].width === width) {
      const a = toScreen(segments[i].from);
      const b = toScreen(segments[i].to);
      if (!last || Math.abs(last[0] - a[0]) > 0.01 || Math.abs(last[1] - a[1]) > 0.01) ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
      last = b;
      i++;
    }
    ctx.stroke();
  }

  if (turtle && options.marks) drawTurtle(ctx, turtle, palette, (p) => toScreen(p), scale);
}

function drawGrid(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  palette: Palette,
  projection: Projection,
  scale: number,
  center: [number, number],
  toScreen: (p: Vec3) => [number, number],
) {
  const step = GRID_STEPS.find((g) => g * scale >= 28) ?? GRID_STEPS[GRID_STEPS.length - 1];
  ctx.save();
  ctx.lineWidth = 1;
  if (projection === "top") {
    const x0 = center[0] - w / 2 / scale;
    const x1 = center[0] + w / 2 / scale;
    const y0 = center[1] - h / 2 / scale;
    const y1 = center[1] + h / 2 / scale;
    ctx.strokeStyle = palette.rule;
    ctx.beginPath();
    for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) {
      if (x === 0) continue;
      const sx = Math.round(toScreen([x, 0, 0])[0]) + 0.5;
      ctx.moveTo(sx, 0);
      ctx.lineTo(sx, h);
    }
    for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) {
      if (y === 0) continue;
      const sy = Math.round(toScreen([0, y, 0])[1]) + 0.5;
      ctx.moveTo(0, sy);
      ctx.lineTo(w, sy);
    }
    ctx.stroke();
    ctx.strokeStyle = palette.ruleStrong;
    ctx.beginPath();
    const [ox, oy] = toScreen([0, 0, 0]);
    ctx.moveTo(Math.round(ox) + 0.5, 0);
    ctx.lineTo(Math.round(ox) + 0.5, h);
    ctx.moveTo(0, Math.round(oy) + 0.5);
    ctx.lineTo(w, Math.round(oy) + 0.5);
    ctx.stroke();
  } else {
    // Isometric: a ground grid around the origin and the three axes in their colours.
    const reach = Math.ceil((Math.max(w, h) / scale / step) * 0.9) * step;
    ctx.strokeStyle = palette.rule;
    ctx.beginPath();
    for (let k = -reach; k <= reach; k += step) {
      const a = toScreen([k, -reach, 0]);
      const b = toScreen([k, reach, 0]);
      const c = toScreen([-reach, k, 0]);
      const d = toScreen([reach, k, 0]);
      ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
      ctx.moveTo(c[0], c[1]);
      ctx.lineTo(d[0], d[1]);
    }
    ctx.stroke();
    const len = step * 3;
    const axes: [Vec3, string][] = [
      [[len, 0, 0], palette.axisX],
      [[0, len, 0], palette.axisY],
      [[0, 0, len], palette.axisZ],
    ];
    const o = toScreen([0, 0, 0]);
    ctx.lineWidth = 1.5;
    for (const [end, color] of axes) {
      const e = toScreen(end);
      ctx.strokeStyle = color;
      ctx.beginPath();
      ctx.moveTo(o[0], o[1]);
      ctx.lineTo(e[0], e[1]);
      ctx.stroke();
    }
  }
  ctx.restore();
}

/** The origin, drawn as a printer's registration mark. */
function drawRegistrationMark(ctx: CanvasRenderingContext2D, [x, y]: [number, number], palette: Palette) {
  ctx.save();
  ctx.strokeStyle = palette.ink;
  ctx.globalAlpha = 0.75;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(x, y, 6.5, 0, Math.PI * 2);
  ctx.moveTo(x - 11, y);
  ctx.lineTo(x + 11, y);
  ctx.moveTo(x, y - 11);
  ctx.lineTo(x, y + 11);
  ctx.stroke();
  ctx.restore();
}

/** The turtle: an arrowhead along its heading; a dashed outline while the pen is up. */
function drawTurtle(
  ctx: CanvasRenderingContext2D,
  turtle: TurtleState,
  palette: Palette,
  toScreen: (p: Vec3) => [number, number],
  scale: number,
) {
  const size = 15 / scale;
  const p = turtle.position;
  const h = turtle.heading;
  const r = turtle.right;
  const at = (fh: number, fr: number): [number, number] =>
    toScreen([p[0] + h[0] * size * fh + r[0] * size * fr, p[1] + h[1] * size * fh + r[1] * size * fr, p[2] + h[2] * size * fh + r[2] * size * fr]);
  const tip = at(1, 0);
  const left = at(-0.55, -0.62);
  const notch = at(-0.22, 0);
  const right = at(-0.55, 0.62);
  ctx.save();
  ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(tip[0], tip[1]);
  ctx.lineTo(left[0], left[1]);
  ctx.lineTo(notch[0], notch[1]);
  ctx.lineTo(right[0], right[1]);
  ctx.closePath();
  if (turtle.penDown) {
    ctx.fillStyle = turtle.color;
    ctx.fill();
    ctx.strokeStyle = palette.ink;
    ctx.lineWidth = 1.25;
    ctx.stroke();
  } else {
    ctx.fillStyle = palette.sheet;
    ctx.globalAlpha = 0.9;
