  toBlob(): Promise<Blob | null> {
    const w = Math.max(320, Math.round(this.width || 800));
    const h = Math.max(240, Math.round(this.height || 600));
    const still = renderStill({ ...this.scene, ghost: [] }, this.options.projection, w, h, { dpr: 2, padding: 32 });
    return new Promise((resolve) => (still.toBlob ? still.toBlob((b) => resolve(b), "image/png") : resolve(null)));
  }

  render(): void {
    const ctx = this.ctx;
    if (!ctx || this.width === 0) return;
    const dpr = this.canvas.width / this.width;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    paint(ctx, this.width, this.height, this.scene, this.palette, this.options.projection, this.scale, this.center, {
