      if (this.pointers.size === 2) this.pinch = { dist: this.pointerDistance(), step: this.step };
    });
    c.addEventListener("pointermove", (e) => {
      const prev = this.pointers.get(e.pointerId);
      if (!prev) return;
      const now = local(e);
      this.pointers.set(e.pointerId, now);
      if (this.pointers.size === 1) this.panBy(now.x - prev.x, now.y - prev.y);
