      }
    });
    const end = (e: PointerEvent) => {
      this.pointers.delete(e.pointerId);
      if (this.pointers.size < 2) this.pinch = null;
    };
    c.addEventListener("pointerup", end);
    c.addEventListener("pointercancel", end);
    c.addEventListener(
      "wheel",
      (e) => {
        e.preventDefault();
        this.wheelAcc += e.deltaY * (e.deltaMode === 1 ? 33 : 1);
        const steps = Math.trunc(this.wheelAcc / 60);
        if (steps !== 0) {
          this.wheelAcc -= steps * 60;
          this.zoomBy(-steps, local(e));
        }
      },
      { passive: false },
    );
    c.addEventListener("keydown", (e) => {
      const pan = 40;
      const keys: Record<string, () => void> = {
        ArrowLeft: () => this.panBy(pan, 0),
        ArrowRight: () => this.panBy(-pan, 0),
        ArrowUp: () => this.panBy(0, pan),
        ArrowDown: () => this.panBy(0, -pan),
        "+": () => this.zoomBy(1),
        "=": () => this.zoomBy(1),
        "-": () => this.zoomBy(-1),
        "0": () => this.fit(),
      };
      const action = keys[e.key];
      if (action && !e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        action();
      }
    });
  }

  private pointerDistance() {
    const [a, b] = [...this.pointers.values()];
    return Math.hypot(a.x - b.x, a.y - b.y);
  }

  private pointerMidpoint() {
    const [a, b] = [...this.pointers.values()];
    return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
  }
}
