const DEFAULT_DIRECTION = new THREE.Vector3(0.62, -1, 0.72).normalize();

/** A 3D view of the turtle's space: orbit, pan, zoom; grid on the ground plane; axes. */
export class View3D {
  readonly canvas: HTMLCanvasElement;
  private renderer: THREE.WebGLRenderer;
  private camera = new THREE.PerspectiveCamera(40, 1, 0.5, 1_000_000);
  private controls: OrbitControls;
  private root = new THREE.Scene();
  private drawing = new THREE.Group();
  private ghost = new THREE.Group();
  private guides = new THREE.Group();
  private turtle = new THREE.Group();
  private materials = new Map<number, LineMaterial>();
  private scene: Scene = EMPTY_SCENE;
  private palette: Palette;
  private width = 1;
  private height = 1;
  private resize: ResizeObserver | null = null;
  private frame = 0;
  private guideReach = 0;
  grid = true;

  constructor(
    private readonly container: HTMLElement,
    private readonly onViewChange?: () => void,
  ) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.canvas = this.renderer.domElement;
    this.canvas.className = "sheet-canvas";
    this.canvas.tabIndex = 0;
    this.canvas.setAttribute("role", "img");
    this.canvas.setAttribute("aria-roledescription", "widok przestrzenny");
    this.canvas.setAttribute("aria-label", "Rysunek żółwia w przestrzeni");
    container.append(this.canvas);
    this.palette = readPalette();
    this.camera.up.set(0, 0, 1);
    this.controls = new OrbitControls(this.camera, this.canvas);
    this.controls.enableDamping = false;
    this.controls.screenSpacePanning = true;
    this.controls.keys = { LEFT: "ArrowLeft", UP: "ArrowUp", RIGHT: "ArrowRight", BOTTOM: "ArrowDown" };
    this.controls.listenToKeyEvents(this.canvas);
    this.controls.addEventListener("change", () => this.requestRender());
    this.canvas.addEventListener("keydown", (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      if (e.key === "+" || e.key === "=") this.zoomBy(1);
      else if (e.key === "-") this.zoomBy(-1);
      else if (e.key === "0") this.fit();
      else return;
      e.preventDefault();
    });
    this.root.add(this.guides, this.ghost, this.drawing, this.turtle);
    this.applyPalette();
    this.resetView();
    if (typeof ResizeObserver !== "undefined") {
      this.resize = new ResizeObserver(() => this.measure());
      this.resize.observe(container);
    }
    this.measure();
  }

  get distanceLabel(): string {
    return `${Math.round(this.camera.position.distanceTo(this.controls.target))}`;
  }

  setScene(scene: Scene): void {
    const segmentsChanged = scene.segments !== this.scene.segments || scene.tween !== this.scene.tween || scene.tween?.t !== this.scene.tween?.t;
    const ghostChanged = scene.ghost !== this.scene.ghost;
    this.scene = scene;
    const { segments, turtle } = animatedScene(scene);
    if (segmentsChanged || true) this.rebuildLines(this.drawing, segments, false);
    if (ghostChanged) this.rebuildLines(this.ghost, scene.ghost, true);
    this.updateGuides();
    this.updateTurtle(turtle);
    this.requestRender();
  }

  refreshPalette(): void {
    this.palette = readPalette();
    this.applyPalette();
    this.guideReach = 0;
    this.updateGuides();
    this.rebuildLines(this.ghost, this.scene.ghost, true);
    this.updateTurtle(animatedScene(this.scene).turtle);
    this.requestRender();
  }

  /** Frame the drawing from the current viewing direction. */
  fit(): void {
    const b = bounds([...this.scene.segments, ...this.scene.ghost], this.scene.turtle ? [this.scene.turtle.position] : [[0, 0, 0]]);
    const center = new THREE.Vector3();
    let radius = 120;
    if (b) {
      center.set((b.min[0] + b.max[0]) / 2, (b.min[1] + b.max[1]) / 2, (b.min[2] + b.max[2]) / 2);
      radius = Math.max(30, Math.hypot(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]) / 2);
    }
    const dir = this.camera.position.clone().sub(this.controls.target);
    if (dir.lengthSq() < 1e-9) dir.copy(DEFAULT_DIRECTION);
    dir.normalize();
    const fov = THREE.MathUtils.degToRad(this.camera.fov);
    const fitH = radius / Math.sin(fov / 2);
    const fitW = radius / Math.sin(Math.atan(Math.tan(fov / 2) * this.camera.aspect));
    const distance = Math.max(fitH, fitW) * 1.08;
    this.controls.target.copy(center);
    this.camera.position.copy(center).addScaledVector(dir, distance);
    this.camera.near = Math.max(0.1, distance / 1000);
    this.camera.far = distance * 100;
    this.camera.updateProjectionMatrix();
    this.controls.update();
    this.changed();
  }

  /** The default camera: front, right and above the drawing, framed to fit. */
  resetView(): void {
    this.controls.target.set(0, 0, 0);
    this.camera.position.copy(DEFAULT_DIRECTION).multiplyScalar(500);
    this.camera.updateProjectionMatrix();
    this.controls.update();
    this.fit();
  }

  zoomBy(steps: number): void {
    const offset = this.camera.position.clone().sub(this.controls.target);
    offset.multiplyScalar(Math.pow(0.8, steps));
    this.camera.position.copy(this.controls.target).add(offset);
    this.controls.update();
    this.changed();
  }

  toBlob(): Promise<Blob | null> {
    this.renderNow();
    return new Promise((resolve) => this.canvas.toBlob((b) => resolve(b), "image/png"));
  }

  destroy(): void {
    cancelAnimationFrame(this.frame);
    this.resize?.disconnect();
    this.controls.dispose();
    this.renderer.dispose();
    this.canvas.remove();
  }

  /** Draw synchronously (used before taking a screenshot). */
  renderNow(): void {
    cancelAnimationFrame(this.frame);
    this.frame = 0;
    this.scaleTurtle();
    this.renderer.render(this.root, this.camera);
  }

  private changed() {
    this.requestRender();
    this.onViewChange?.();
  }

  private requestRender() {
    if (this.frame) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = 0;
      this.renderNow();
    });
  }

  private applyPalette() {
    this.renderer.setClearColor(new THREE.Color(this.palette.sheet), 1);
  }

  private measure() {
    const r = this.container.getBoundingClientRect();
    this.width = Math.max(1, Math.round(r.width));
    this.height = Math.max(1, Math.round(r.height));
    this.renderer.setPixelRatio(Math.min(2, globalThis.devicePixelRatio || 1));
