    for (const s of segments) {
      const w = dashed ? 1.5 : s.width;
      if (!byWidth.has(w)) byWidth.set(w, []);
      byWidth.get(w)!.push(s);
    }
    const c = new THREE.Color();
    for (const [width, list] of byWidth) {
      const positions = new Float32Array(list.length * 6);
      const colors = new Float32Array(list.length * 6);
      list.forEach((s, i) => {
        positions.set([...s.from, ...s.to], i * 6);
        c.set(dashed ? this.palette.ghost : s.color);
        colors.set([c.r, c.g, c.b, c.r, c.g, c.b], i * 6);
      });
      const geom = new LineSegmentsGeometry();
      geom.setPositions(positions);
      geom.setColors(colors);
      const line = new LineSegments2(geom, this.material(width, dashed));
      if (dashed) line.computeLineDistances();
      group.add(line);
    }
  }

  /** Ground grid, axes and the registration mark, sized to the drawing. */
  private updateGuides() {
    const b = bounds([...this.scene.segments, ...this.scene.ghost]);
    const extent = b ? Math.max(...b.max.map(Math.abs), ...b.min.map(Math.abs)) : 100;
    const steps = [50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000, 100000];
    const reach = steps.find((s) => s >= extent * 1.15) ?? 100000;
    if (reach === this.guideReach) return;
    this.guideReach = reach;
    for (const child of this.guides.children) {
      const obj = child as THREE.Mesh;
      obj.geometry?.dispose();
    }
    this.guides.clear();
    const p = this.palette;
    const divisions = 20;
    const grid = new THREE.GridHelper(reach * 2, divisions, new THREE.Color(p.ruleStrong), new THREE.Color(p.rule));
    grid.rotation.x = Math.PI / 2;
    grid.visible = this.grid;
    this.guides.add(grid);
    const axisLen = reach * 0.6;
    const axes: [THREE.Vector3, string, string][] = [
      [new THREE.Vector3(axisLen, 0, 0), p.axisX, "X"],
      [new THREE.Vector3(0, axisLen, 0), p.axisY, "Y"],
      [new THREE.Vector3(0, 0, axisLen), p.axisZ, "Z"],
