    for (const [end, color, label] of axes) {
      const geom = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), end]);
      this.guides.add(new THREE.Line(geom, new THREE.LineBasicMaterial({ color })));
      this.guides.add(this.label(label, color, end.clone().multiplyScalar(1.06), reach * 0.05));
