    const ring: THREE.Vector3[] = [];
    for (let i = 0; i <= 48; i++) ring.push(new THREE.Vector3(Math.cos((i / 48) * Math.PI * 2) * r, Math.sin((i / 48) * Math.PI * 2) * r, 0));
    const ink = new THREE.LineBasicMaterial({ color: p.ink, transparent: true, opacity: 0.75 });
    this.guides.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(ring), ink));
    const cross = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(-r * 1.7, 0, 0),
      new THREE.Vector3(r * 1.7, 0, 0),
      new THREE.Vector3(0, -r * 1.7, 0),
      new THREE.Vector3(0, r * 1.7, 0),
    ]);
