  refreshPalette(): void {
    this.palette = readPalette();
    this.applyPalette();
    this.guideReach = 0;
    this.updateGuides();
    this.rebuildLines(this.ghost, this.scene.ghost, true);
    this.updateTurtle(animatedScene(this.scene).turtle);
    this.requestRender();
  }

  /** Frame the drawing from the current viewing direction. */
  fit(): void {
    const b = bounds([...this.scene.segments, ...this.scene.ghost], this.scene.turtle ? [this.scene.turtle.position] : [[0, 0, 0]]);
    const center = new THREE.Vector3();
    let radius = 120;
    if (b) {
      center.set((b.min[0] + b.max[0]) / 2, (b.min[1] + b.max[1]) / 2, (b.min[2] + b.max[2]) / 2);
      radius = Math.max(30, Math.hypot(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]) / 2);
    }
    const dir = this.camera.position.clone().sub(this.controls.target);
    if (dir.lengthSq() < 1e-9) dir.copy(DEFAULT_DIRECTION);
    dir.normalize();
    const fov = THREE.MathUtils.degToRad(this.camera.fov);
    const fitH = radius / Math.sin(fov / 2);
    const fitW = radius / Math.sin(Math.atan(Math.tan(fov / 2) * this.camera.aspect));
    const distance = Math.max(fitH, fitW) * 1.08;
    this.controls.target.copy(center);
    this.camera.position.copy(center).addScaledVector(dir, distance);
    this.camera.near = Math.max(0.1, distance / 1000);
    this.camera.far = distance * 100;
    this.camera.updateProjectionMatrix();
    this.controls.update();
    this.changed();
  }

  /** The default camera: front, right and above the drawing, framed to fit. */
  resetView(): void {
    this.controls.target.set(0, 0, 0);
    this.camera.position.copy(DEFAULT_DIRECTION).multiplyScalar(500);
    this.camera.updateProjectionMatrix();
    this.controls.update();
    this.fit();
  }

  zoomBy(steps: number): void {
    const offset = this.camera.position.clone().sub(this.controls.target);
    offset.multiplyScalar(Math.pow(0.8, steps));
    this.camera.position.copy(this.controls.target).add(offset);
    this.controls.update();
    this.changed();
  }

  toBlob(): Promise<Blob | null> {
    this.renderNow();
    return new Promise((resolve) => this.canvas.toBlob((b) => resolve(b), "image/png"));
  }

  destroy(): void {
    cancelAnimationFrame(this.frame);
    this.resize?.disconnect();
    this.controls.dispose();
    this.renderer.dispose();
    this.canvas.remove();
  }

  /** Draw synchronously (used before taking a screenshot). */
  renderNow(): void {
    cancelAnimationFrame(this.frame);
    this.frame = 0;
    this.scaleTurtle();
    this.renderer.render(this.root, this.camera);
  }

  private changed() {
    this.requestRender();
    this.onViewChange?.();
  }

  private requestRender() {
    if (this.frame) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = 0;
      this.renderNow();
    });
  }

  private applyPalette() {
    this.renderer.setClearColor(new THREE.Color(this.palette.sheet), 1);
  }

  private measure() {
    const r = this.container.getBoundingClientRect();
    this.width = Math.max(1, Math.round(r.width));
    this.height = Math.max(1, Math.round(r.height));
    this.renderer.setPixelRatio(Math.min(2, globalThis.devicePixelRatio || 1));
    this.renderer.setSize(this.width, this.height, true);
    this.camera.aspect = this.width / this.height;
    this.camera.updateProjectionMatrix();
    for (const m of this.materials.values()) m.resolution.set(this.width, this.height);
    this.renderNow();
  }

  private material(width: number, dashed: boolean): LineMaterial {
    const key = dashed ? -width : width;
    let m = this.materials.get(key);
    if (!m) {
      m = new LineMaterial({ linewidth: width, vertexColors: true, dashed, dashSize: 7, gapSize: 5, worldUnits: false });
      m.resolution.set(this.width, this.height);
      this.materials.set(key, m);
    }
    return m;
  }

  private rebuildLines(group: THREE.Group, segments: readonly Segment[], dashed: boolean) {
    for (const child of group.children) (child as LineSegments2).geometry.dispose();
    group.clear();
    const byWidth = new Map<number, Segment[]>();
    for (const s of segments) {
      const w = dashed ? 1.5 : s.width;
      if (!byWidth.has(w)) byWidth.set(w, []);
      byWidth.get(w)!.push(s);
    }
    const c = new THREE.Color();
    for (const [width, list] of byWidth) {
      const positions = new Float32Array(list.length * 6);
      const colors = new Float32Array(list.length * 6);
      list.forEach((s, i) => {
        positions.set([...s.from, ...s.to], i * 6);
        c.set(dashed ? this.palette.ghost : s.color);
        colors.set([c.r, c.g, c.b, c.r, c.g, c.b], i * 6);
      });
      const geom = new LineSegmentsGeometry();
      geom.setPositions(positions);
      geom.setColors(colors);
      const line = new LineSegments2(geom, this.material(width, dashed));
      if (dashed) line.computeLineDistances();
      group.add(line);
    }
  }

  /** Ground grid, axes and the registration mark, sized to the drawing. */
  private updateGuides() {
    const b = bounds([...this.scene.segments, ...this.scene.ghost]);
    const extent = b ? Math.max(...b.max.map(Math.abs), ...b.min.map(Math.abs)) : 100;
    const steps = [50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000, 100000];
    const reach = steps.find((s) => s >= extent * 1.15) ?? 100000;
    if (reach === this.guideReach) return;
    this.guideReach = reach;
    for (const child of this.guides.children) {
      const obj = child as THREE.Mesh;
      obj.geometry?.dispose();
    }
    this.guides.clear();
    const p = this.palette;
    const divisions = 20;
    const grid = new THREE.GridHelper(reach * 2, divisions, new THREE.Color(p.ruleStrong), new THREE.Color(p.rule));
    grid.rotation.x = Math.PI / 2;
    grid.visible = this.grid;
    this.guides.add(grid);
    const axisLen = reach * 0.6;
    const axes: [THREE.Vector3, string, string][] = [
      [new THREE.Vector3(axisLen, 0, 0), p.axisX, "X"],
      [new THREE.Vector3(0, axisLen, 0), p.axisY, "Y"],
      [new THREE.Vector3(0, 0, axisLen), p.axisZ, "Z"],
    ];
    for (const [end, color, label] of axes) {
      const geom = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), end]);
      this.guides.add(new THREE.Line(geom, new THREE.LineBasicMaterial({ color })));
      this.guides.add(this.label(label, color, end.clone().multiplyScalar(1.06), reach * 0.05));
    }
    // Registration mark at the origin, lying on the ground plane.
    const r = reach * 0.03;
    const ring: THREE.Vector3[] = [];
    for (let i = 0; i <= 48; i++) ring.push(new THREE.Vector3(Math.cos((i / 48) * Math.PI * 2) * r, Math.sin((i / 48) * Math.PI * 2) * r, 0));
    const ink = new THREE.LineBasicMaterial({ color: p.ink, transparent: true, opacity: 0.75 });
    this.guides.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(ring), ink));
    const cross = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(-r * 1.7, 0, 0),
      new THREE.Vector3(r * 1.7, 0, 0),
      new THREE.Vector3(0, -r * 1.7, 0),
      new THREE.Vector3(0, r * 1.7, 0),
    ]);
    this.guides.add(new THREE.LineSegments(cross, ink));
  }

  private label(text: string, color: string, at: THREE.Vector3, size: number): THREE.Sprite {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 64;
    const ctx = canvas.getContext("2d")!;
    ctx.fillStyle = color;
    ctx.font = "600 40px 'Archivo Variable', system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, 32, 34);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: false, transparent: true }));
    sprite.position.copy(at);
    sprite.scale.set(size, size, size);
    return sprite;
  }

  /** An arrowhead in the heading–right plane with a fin along up: position, heading and roll at a glance. */
  private updateTurtle(t: TurtleState | null) {
    for (const child of this.turtle.children) (child as THREE.Mesh).geometry?.dispose();
    this.turtle.clear();
    if (!t) return;
    const shape = new THREE.BufferGeometry();
    // Local frame: +X heading, +Y right, +Z up.
    const v = new Float32Array([
      1, 0, 0, -0.55, -0.62, 0, -0.22, 0, 0,
      1, 0, 0, -0.22, 0, 0, -0.55, 0.62, 0,
      // fin
      0.35, 0, 0, -0.45, 0, 0, -0.45, 0, 0.55,
    ]);
    shape.setAttribute("position", new THREE.BufferAttribute(v, 3));
    const color = new THREE.Color(t.color);
    const body = new THREE.Mesh(
      shape,
      new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, transparent: !t.penDown, opacity: t.penDown ? 1 : 0.18 }),
    );
    const edges = new THREE.LineSegments(
      new THREE.EdgesGeometry(shape),
      t.penDown
        ? new THREE.LineBasicMaterial({ color: this.palette.ink })
        : new THREE.LineDashedMaterial({ color: this.palette.ink, dashSize: 0.12, gapSize: 0.09 }),
    );
    if (!t.penDown) edges.computeLineDistances();
    const holder = new THREE.Group();
    holder.add(body, edges);
    const basis = new THREE.Matrix4().makeBasis(
      new THREE.Vector3(...t.heading),
      new THREE.Vector3(...t.right),
      new THREE.Vector3(...t.up),
    );
    holder.quaternion.setFromRotationMatrix(basis);
    holder.position.set(...t.position);
    this.turtle.add(holder);
    this.scaleTurtle();
  }

  /** Keep the turtle about the same size on screen at any distance. */
  private scaleTurtle() {
    const holder = this.turtle.children[0];
    if (!holder) return;
    const d = this.camera.position.distanceTo(holder.position);
    const s = (d * Math.tan(THREE.MathUtils.degToRad(this.camera.fov / 2)) * 2 * 18) / this.height;
    holder.scale.setScalar(s);
  }
}
