      action("save-file", "Zapisz .logo", "download", () => this.downloadProgram(), { "aria-label": "Pobierz program jako plik .logo" }),
      action("copy-link", "Link", "link", () => void this.copyLink(), { "aria-label": "Kopiuj link do programu" }),
      action("export-png", "PNG", "image", () => void this.exportPng(), { "aria-label": "Pobierz rysunek jako PNG" }),
      action("backups", "Kopie", "restore", () => this.showBackups(), { "aria-label": "Wcześniejsze szkice" }),
