    this.speedOutput = h("output", { id: "speed-value", for: "speed", class: "speed-value" }, speedName(this.runner.speed));
    const shortcutsPanel = h(
      "div",
      { class: "popover", id: "shortcuts-panel", hidden: true, role: "region", "aria-label": "Skróty klawiszowe" },
      h("p", { class: "popover-title" }, "Skróty klawiszowe"),
      h("dl", { class: "keys" }, ...SHORTCUTS.flatMap(([what, keys]) => [h("dt", {}, what), h("dd", {}, ...kbd(keys))])),
      h("p", { class: "popover-note" }, "Na arkuszu: strzałki przesuwają, + i − zmieniają skalę, 0 dopasowuje widok."),
    );
    const shortcutsButton = h(
