    this.errorBox = h("div", { class: "error-box", role: "alert", hidden: true });

    const editorHost = h("div", { class: "editor-host" });

    this.sheetNotice = h("div", { class: "sheet-notice", hidden: true });
    this.resetViewButton = h(
      "button",
      { type: "button", class: "tool", "aria-label": "Widok domyślny", title: "Widok domyślny", onclick: () => this.view?.resetView() },
      icon("orbit"),
    );
    this.gridButton = h(
      "button",
      { type: "button", class: "tool", "aria-label": "Siatka", title: "Siatka", "aria-pressed": "true", onclick: () => this.toggleGrid() },
