      h("button", { type: "button", class: "tool", "aria-label": "Powiększ", title: "Powiększ (+)", onclick: () => this.view?.zoomBy(1) }, icon("zoomIn")),
      h("button", { type: "button", class: "tool", "aria-label": "Dopasuj rysunek", title: "Dopasuj (0)", "data-action": "fit", onclick: () => this.view?.fit() }, icon("fit")),
      this.resetViewButton,
      this.gridButton,
    );
