        deps.challengeSlot ?? null,
        h(
          "div",
          { class: "runbar", role: "toolbar", "aria-label": "Wykonanie programu" },
          this.buttons.run,
          this.buttons.step,
          this.buttons.pause,
          this.buttons.reset,
          h("div", { class: "speed" }, h("label", { for: "speed" }, "Szybkość"), this.speedInput, this.speedOutput),
          h("div", { class: "popover-anchor" }, shortcutsButton, shortcutsPanel),
        ),
        editorHost,
        this.errorBox,
        this.status,
      ),
