    );

    this.editor = createEditor(editorHost, {
      doc: this.draftText(this.mode),
      onChange: (text) => this.onEdit(text),
      label: "Program w języku Logo",
      describedBy: "run-status",
    });
    this.title.textContent = this.draftTitle(this.mode);
    this.mountView();
    this.syncControls();
    this.renderStatus();
    this.updateImprint();
  }

  // ---------------------------------------------------------------- public API

  get source(): string {
    return this.editor.getText();
  }

  get state(): RunState {
    return this.runner.state;
  }

  get inChallenge(): ChallengeContext | null {
    return this.challenge;
  }

  /** Put a program into a mode's editor as if pasted, keeping any unsaved draft as a copy. */
  load(source: string, mode: Mode, title: string = DEFAULT_TITLE[mode]): void {
    if (this.challenge) this.leaveChallenge(false);
    if (mode !== this.mode) this.setMode(mode);
    this.backupIfDirty(mode, `przed wczytaniem: ${title}`);
    this.deps.store.set(`loaded.${mode}`, source);
    this.deps.store.set(`title.${mode}`, title);
    this.deps.store.set(`draft.${mode}`, source);
    this.runner.reset();
    this.haltedByEdit = false;
    this.editor.setText(source);
    this.title.textContent = title;
    this.refresh();
  }

  /** Run to the end without animation, frame the drawing, and resolve once it is on screen. */
  async runInstantly(): Promise<RunResult> {
    await this.view3dLoading;
    const speed = this.runner.speed;
    this.runner.speed = this.runner.maxSpeed;
    this.runner.run(this.source, this.mode);
    this.scheduler().flush?.();
    while (this.runner.state === "running") this.stepLoopOnce();
    this.runner.speed = speed;
    this.tween = null;
    this.refresh();
    this.view?.fit();
    this.refresh();
    await nextPaint();
    const { segments, error } = this.runner.view;
    return {
      segments: segments.map((s) => ({ from: [...s.from], to: [...s.to], color: s.color, width: s.width })),
      error: error ? { ...error } : null,
    };
  }

  setMode(mode: Mode): void {
    if (mode === this.mode) return;
    if (this.challenge) return;
    this.runner.reset();
    this.haltedByEdit = false;
    this.mode = mode;
    this.deps.store.set("mode", mode);
    this.editor.setText(this.draftText(mode));
    this.title.textContent = this.draftTitle(mode);
    this.mountView();
    this.syncControls();
    this.refresh();
  }

  command(name: "run" | "step" | "pause" | "reset"): void {
    const r = this.runner;
    this.haltedByEdit = false;
    if (name === "run") {
      r.run(this.source, this.mode);
      if (r.state === "done" || r.state === "error") this.afterRunSettled();
    } else if (name === "step") r.step(this.source, this.mode);
    else if (name === "pause") {
      if (r.state === "running") r.pause();
      else if (r.state === "paused") r.resume();
    } else r.reset();
    this.refresh();
    this.ensureLoop();
  }

  /** Enter a challenge: its own document, its mode, its target as fold lines. */
  enterChallenge(ctx: ChallengeContext): void {
    if (this.challenge?.id !== ctx.id && this.challenge) this.leaveChallenge(false);
    if (ctx.mode !== this.mode) {
      this.challenge = null;
      this.setMode(ctx.mode);
    }
    this.challenge = ctx;
    this.runner.reset();
    this.editor.setText(ctx.text);
    this.title.textContent = ctx.title;
    this.syncControls();
    this.refresh();
    this.view?.fit();
  }

  leaveChallenge(notify = true): void {
    if (!this.challenge) return;
    this.challenge = null;
    this.runner.reset();
    this.editor.setText(this.draftText(this.mode));
    this.title.textContent = this.draftTitle(this.mode);
    this.syncControls();
    this.refresh();
    if (notify) this.deps.onExitChallenge?.();
  }

  /** Run the attempt to the end (instantly) for checking. */
  async runForCheck(): Promise<RunResult> {
    return this.runInstantly();
  }

  focusEditor(): void {
    this.editor.focus();
  }

  fit(): void {
    this.view?.fit();
  }

  onThemeChange(): void {
    this.view?.refreshPalette();
  }

  /** Keyboard shortcuts; returns true when handled. */
  handleShortcut(e: KeyboardEvent): boolean {
    const mod = e.ctrlKey || e.metaKey;
    if (!mod || e.altKey) return false;
    let name: "run" | "step" | "pause" | "reset" | null = null;
    if (e.key === "Enter") name = e.shiftKey ? "step" : "run";
    else if (e.shiftKey && (e.code === "Space" || e.key === " ")) name = "pause";
    else if (e.shiftKey && e.key === "Backspace") name = "reset";
    if (!name) return false;
    e.preventDefault();
    this.command(name);
    return true;
  }

  backups(): Backup[] {
    return readJSON<Backup[]>(this.deps.store, "backups", []);
  }

  restoreBackup(index: number): void {
    const list = this.backups();
    const b = list[index];
    if (!b) return;
    if (this.challenge) this.leaveChallenge(false);
    if (b.mode !== this.mode) this.setMode(b.mode);
    this.backupIfDirty(b.mode, "przed przywróceniem kopii");
    const remaining = this.backups().filter((x) => !(x.at === b.at && x.text === b.text));
    writeJSON(this.deps.store, "backups", remaining);
    this.deps.store.set(`draft.${b.mode}`, b.text);
    this.deps.store.set(`title.${b.mode}`, b.title);
    this.deps.store.remove(`loaded.${b.mode}`);
    this.runner.reset();
    this.editor.setText(b.text);
    this.title.textContent = b.title;
    this.refresh();
  }

  destroy(): void {
    this.destroyed = true;
    if (this.loopId !== null) this.scheduler().cancel(this.loopId);
    this.editor.destroy();
    this.view?.destroy();
  }

  // ---------------------------------------------------------------- drafts

  private draftText(mode: Mode): string {
    return this.deps.store.get(`draft.${mode}`) ?? STARTERS[mode];
  }

  private draftTitle(mode: Mode): string {
    return this.deps.store.get(`title.${mode}`) ?? DEFAULT_TITLE[mode];
  }

  /** A draft is the learner's own work unless it is empty, a starter, an example, or what was last loaded untouched. */
  private isPristine(mode: Mode, text: string): boolean {
    const t = text.trim();
    if (t === "") return true;
    if (t === STARTERS[mode].trim()) return true;
    if (EXAMPLES.some((e) => e.source.trim() === t)) return true;
    const loaded = this.deps.store.get(`loaded.${mode}`);
    if (loaded !== null && loaded.trim() === t) return true;
    return this.backups().some((b) => b.text.trim() === t);
  }

  private backupIfDirty(mode: Mode, _reason: string): void {
    const current = mode === this.mode && !this.challenge ? this.editor.getText() : this.draftText(mode);
    if (this.isPristine(mode, current)) return;
    const list = this.backups();
    list.unshift({ mode, text: current, title: this.draftTitle(mode), at: new Date().toISOString() });
    writeJSON(this.deps.store, "backups", list.slice(0, 12));
    this.deps.toast.show(`Twój szkic ${mode.toUpperCase()} zapisano w kopiach.`, {
      action: "Przywróć",
      onAction: () => this.restoreBackup(0),
    });
  }

  private onEdit(text: string): void {
    if (this.challenge) this.challenge.save(text);
    else {
      this.deps.store.set(`draft.${this.mode}`, text);
      const loaded = this.deps.store.get(`loaded.${this.mode}`);
      if (loaded !== null && loaded !== text && this.draftTitle(this.mode) !== DEFAULT_TITLE[this.mode]) {
        // Edited away from the loaded example: it is the learner's draft now.
        this.deps.store.set(`title.${this.mode}`, `${this.draftTitle(this.mode).replace(/ \(zmieniony\)$/, "")} (zmieniony)`);
        this.title.textContent = this.draftTitle(this.mode);
      }
    }
    const st = this.runner.state;
    if (st === "running" || st === "paused") {
      // The highlight would point at code that no longer exists: stop, keep the drawing.
      this.runner.halt();
      this.haltedByEdit = true;
      this.refresh();
    } else if (st === "error") {
      this.errorBox.hidden = true;
      this.renderStatus();
    }
  }

  // ---------------------------------------------------------------- views

  private mountView(): void {
    this.view?.destroy();
    this.view = null;
    this.sheetNotice.hidden = true;
    this.sheet.dataset.mode = this.mode;
    this.element.dataset.mode = this.mode;
    const onViewChange = () => this.updateImprint();
    if (this.mode === "2d") {
      this.view = new View2D(this.sheet, { projection: "top", onViewChange, label: "Rysunek żółwia na płaszczyźnie" });
    } else if (this.webglReason) {
      this.view = new View2D(this.sheet, { projection: "iso", onViewChange, label: "Rysunek żółwia w rzucie izometrycznym" });
      this.sheetNotice.hidden = false;
      this.sheetNotice.replaceChildren(
        h("strong", {}, "Widok 3D jest wyłączony. "),
        `${this.webglReason} Programy działają dalej, a rysunek widać tu w nieruchomym rzucie izometrycznym.`,
      );
    } else {
      const placeholder = this.view;
      void placeholder;
      this.view3dLoading = import("../views/view3d")
        .then(({ View3D }) => {
          if (this.destroyed || this.mode !== "3d" || this.view) return;
          this.view = new View3D(this.sheet, onViewChange);
          this.view.grid = this.gridOn();
          this.refresh();
          this.view.fit();
        })
        .catch(() => {
          this.webglReason = "Nie udało się wczytać modułu widoku 3D.";
          if (this.mode === "3d") this.mountView();
        });
    }
    if (this.view) this.view.grid = this.gridOn();
    this.view?.canvas.parentElement === this.sheet && this.sheet.prepend(this.view.canvas);
    this.resetViewButton.hidden = this.mode !== "3d" || !!this.webglReason;
  }

  private gridOn(): boolean {
    return this.deps.store.get("grid") !== "off";
  }

  private toggleGrid(): void {
    const on = !this.gridOn();
    this.deps.store.set("grid", on ? "on" : "off");
    this.gridButton.setAttribute("aria-pressed", String(on));
    if (this.view) {
      this.view.grid = on;
      if (this.mode === "3d" && !this.webglReason) this.view.refreshPalette();
      else this.refresh();
    }
  }

  // ---------------------------------------------------------------- run loop

  private scheduler() {
    return this.deps.scheduler as Scheduler & { flush?: () => void };
  }

  private setSpeed(level: number): void {
    this.runner.speed = level;
    this.deps.store.set("speed", String(this.runner.speed));
    this.speedOutput.textContent = speedName(this.runner.speed);
  }

  private ensureLoop(): void {
    if (this.loopId !== null || this.destroyed) return;
    const loop = () => {
      this.loopId = null;
      if (this.destroyed) return;
      this.refresh();
      if (this.runner.state === "running" || this.tween) this.loopId = this.scheduler().frame(loop);
    };
    this.loopId = this.scheduler().frame(loop);
  }

  private stepLoopOnce(): void {
    // Only used by runInstantly when no scheduler flush exists.
    this.runner.pause();
    while (this.runner.state === "paused") this.runner.step(this.source, this.mode);
  }

  private afterRunSettled(): void {
    this.view?.fit();
  }

  /** Pull the runner's view into the sheet, the editor markers and the controls. */
  private refresh(): void {
    const r = this.runner;
    const view = r.view;
    const now = this.scheduler().now();
    const state = r.state;

    // Animate the latest command: from the previous turtle to the current one.
    if (view.current !== this.lastCurrent && state !== "idle") {
      const cps = SPEEDS[r.speed - 1];
      const duration = this.reducedMotion || cps === Infinity ? 0 : state === "paused" ? 220 : Math.min(400, 1000 / cps);
      this.tween =
        duration > 0 && this.prevTurtle
          ? { from: this.prevTurtle, start: now, duration, drewSegment: view.segments.length > this.prevCount }
          : null;
      this.lastCurrent = view.current;
    }
    if (state === "idle") {
      this.tween = null;
      this.lastCurrent = null;
    }
    let t = 1;
    if (this.tween) {
      t = (now - this.tween.start) / this.tween.duration;
      if (t >= 1) this.tween = null;
    }
    this.prevTurtle = view.turtle;
    this.prevCount = view.segments.length;

    const scene: Scene = {
      segments: view.segments,
      turtle: state === "idle" ? HOME_TURTLE : view.turtle,
      tween: this.tween ? { from: this.tween.from, t, drewSegment: this.tween.drewSegment } : null,
      ghost: this.challenge?.ghost ?? EMPTY_SCENE.ghost,
    };
    this.view?.setScene(scene);

    if (state !== this.lastState) {
      if ((state === "done" || state === "error") && (this.lastState === "running" || this.lastState === "paused")) this.afterRunSettled();
      this.lastState = state;
      this.renderStatus();
    }
    this.editor.setCurrent(state === "running" || state === "paused" ? view.current : null);
    this.showError(view.error);
    this.syncControls();
    this.updateImprint();
  }

  private showError(error: LangError | null): void {
    const key = error ? `${error.line}:${error.column}:${error.message}` : "";
    if (this.errorBox.dataset.key === key) return;
    this.errorBox.dataset.key = key;
    if (!error) {
      this.errorBox.hidden = true;
      this.editor.setError(null);
      return;
    }
    this.editor.setError({ line: error.line, column: error.column, message: error.message, length: this.tokenLength(error) });
    this.errorBox.hidden = false;
    const parse = this.runner.view.segments.length === 0 ? "" : " Rysunek zatrzymał się w tym miejscu.";
    this.errorBox.replaceChildren(
      h(
        "button",
        { type: "button", class: "error-where", onclick: () => this.editor.reveal(error.line, error.column) },
        `Wiersz ${error.line}, kolumna ${error.column}`,
      ),
      h("span", { class: "error-message" }, error.message + parse),
    );
  }

  private tokenLength(error: LangError): number {
    const line = this.source.split("\n")[error.line - 1] ?? "";
    const rest = line.slice(error.column - 1);
    const m = /^("[^"\n]*"?|[\p{L}\p{N}_.:#]+|<=|>=|<>|.)/u.exec(rest);
    return Math.max(1, m ? m[0].length : 1);
  }

  private renderStatus(): void {
    const r = this.runner;
    const v = r.view;
    const segs = v.segments.length;
    const summary = `${formatCount(segs)} ${plural(segs, "odcinek", "odcinki", "odcinków")}`;
    let text: string;
    switch (r.state) {
      case "idle":
        text = `Gotowe do uruchomienia. ${MOD}+Enter uruchamia program.`;
        break;
      case "running":
        text = "Żółw rysuje…";
        break;
      case "paused":
        text = this.haltedByEdit
          ? "Zatrzymano, bo zmienił się kod. Uruchom ponownie, gdy skończysz pisać."
          : `Pauza${v.current ? ` po wierszu ${v.current.line}` : ""}. «Krok» wykona następne polecenie.`;
        break;
      case "stopped":
        text = "Zatrzymano, bo zmienił się kod. Uruchom ponownie, gdy skończysz pisać.";
        break;
      case "done":
        text = `Gotowe: ${summary}.`;
        break;
      case "error":
        text = segs ? `Błąd w czasie działania. Zostało ${summary}.` : "Błąd w programie, więc nic nie zostało narysowane.";
        break;
    }
    this.status.textContent = text;
    this.status.dataset.state = r.state;
  }

  private syncControls(): void {
    const st = this.runner.state;
    const pause = this.buttons.pause;
    const resuming = st === "paused";
    pause.disabled = !(st === "running" || st === "paused");
    pause.setAttribute("aria-pressed", String(resuming));
    const label = resuming ? "Wznów" : "Pauza";
    if (pause.dataset.label !== label) {
      pause.dataset.label = label;
      pause.replaceChildren(icon(resuming ? "resume" : "pause"), h("span", { class: "btn-label" }, label));
      pause.title = `${label} (${MOD}+Shift+Spacja)`;
    }
    this.buttons.reset.disabled = st === "idle";
    for (const b of this.modeButtons) {
      const on = b.dataset.mode === this.mode;
      b.setAttribute("aria-pressed", String(on));
      b.disabled = !!this.challenge && !on;
      b.title = this.challenge && !on ? "W wyzwaniu tryb jest ustalony" : "";
    }
    this.element.dataset.state = st;
  }

  private updateImprint(): void {
    const v = this.runner.view;
    const segs = v.segments;
    const colors: string[] = [];
    for (const s of segs) if (!colors.includes(s.color)) colors.push(s.color);
    const turtle = this.runner.state === "idle" ? HOME_TURTLE : v.turtle;
    const [x, y, z] = turtle.position.map((n) => (Math.abs(n) < 5e-5 ? 0 : Number(n.toFixed(1))));
    const heading = (((Math.atan2(turtle.heading[0], turtle.heading[1]) * 180) / Math.PI + 360) % 360).toFixed(0);
    const scale = this.view?.scaleLabel;
    const parts = [
      h("span", { class: "imprint-name" }, this.title.textContent ?? ""),
      h("span", {}, this.mode.toUpperCase()),
      scale ? h("span", {}, `skala ${scale}`) : null,
      h("span", { "data-role": "segment-count" }, `${formatCount(segs.length)} ${plural(segs.length, "odcinek", "odcinki", "odcinków")}`),
    ];
    const bar = h(
      "span",
      { class: "colorbar", role: "list", "aria-label": colors.length ? "Kolory na rysunku" : "Brak kolorów" },
      ...colors.slice(0, 12).map((c) => h("span", { class: "chip", role: "listitem", title: c, "aria-label": c, style: `--c:${c}` })),
    );
    const where =
      this.mode === "2d"
        ? `żółw ${fmt(x)}, ${fmt(y)} · kierunek ${heading}°`
        : `żółw ${fmt(x)}, ${fmt(y)}, ${fmt(z)}`;
    this.imprint.replaceChildren(
      h("span", { class: "imprint-main" }, ...interleave(parts.filter(Boolean) as HTMLElement[])),
      bar,
      h("span", { class: "imprint-turtle" }, where, turtle.penDown ? "" : " · pisak podniesiony"),
    );
  }

  // ---------------------------------------------------------------- files and sharing

  private openFile(input: HTMLInputElement): void {
    const file = input.files?.[0];
    input.value = "";
    if (!file) return;
    void file.text().then((text) => {
      const normalized = text.replace(/\r\n?/g, "\n").replace(/^﻿/, "");
      const mode: Mode = /(^|[\s[\]])(gora|góra|dol|dół|pp|pl|przechylprawo|przechyllewo|pitchup|pitchdown|rollright|rollleft)\s/iu.test(normalized)
        ? "3d"
        : this.mode;
      const title = file.name.replace(/\.(logo|txt)$/i, "") || DEFAULT_TITLE[mode];
      this.load(normalized, mode, title);
      this.deps.toast.show(`Otwarto plik «${file.name}».`);
    });
  }

  private downloadProgram(): void {
    const name = slug(this.title.textContent || DEFAULT_TITLE[this.mode]) || "program";
    download(new Blob([this.source], { type: "text/plain;charset=utf-8" }), `${name}.logo`);
    this.deps.toast.show(`Pobrano plik «${name}.logo».`);
  }

  private async copyLink(): Promise<void> {
    const { permalink } = await import("../app/share");
    const url = await permalink(this.source, this.mode);
    let copied = false;
    try {
      await navigator.clipboard?.writeText(url);
      copied = !!navigator.clipboard;
    } catch {
      copied = false;
    }
    this.deps.toast.show(copied ? "Link do programu skopiowano do schowka." : "Skopiuj ten link:", { detail: url });
  }

  private async exportPng(): Promise<void> {
    if (!this.view) return;
    if (this.runner.state === "idle") {
      this.deps.toast.show("Najpierw uruchom program, żeby było co zapisać.");
      return;
    }
    const blob = await this.view.toBlob();
    if (!blob) {
      this.deps.toast.show("Nie udało się utworzyć obrazu w tej przeglądarce.");
      return;
    }
    const name = slug(this.title.textContent || "rysunek") || "rysunek";
    download(blob, `${name}.png`);
    this.deps.toast.show(`Pobrano obraz «${name}.png».`);
  }

  private showBackups(): void {
    const list = this.backups();
    if (list.length === 0) {
      this.deps.toast.show("Nie ma jeszcze kopii. Gdy wczytasz przykład albo plik na swój szkic, szkic trafi tutaj.");
      return;
    }
    this.deps.toast.list(
      "Wcześniejsze szkice",
      list.map((b, i) => ({
        label: `${b.title} · ${b.mode.toUpperCase()} · ${new Date(b.at).toLocaleString("pl-PL", { dateStyle: "short", timeStyle: "short" })}`,
        detail: b.text.split("\n").find((l) => l.trim() && !l.trim().startsWith(";"))?.trim() ?? "",
        onPick: () => this.restoreBackup(i),
      })),
    );
  }
}

const HOME_TURTLE: TurtleState = {
  position: [0, 0, 0],
  heading: [0, 1, 0],
  right: [1, 0, 0],
  up: [0, 0, 1],
  penDown: true,
  color: "#16866a",
  width: 3,
};

function fmt(n: number): string {
  return String(n).replace("-", "−");
}

function interleave(parts: HTMLElement[]): Node[] {
  const out: Node[] = [];
  parts.forEach((p, i) => {
    if (i) out.push(h("span", { class: "sep", "aria-hidden": "true" }, "·"));
    out.push(p);
  });
  return out;
}

export function kbd(keys: string): HTMLElement[] {
  return keys.split("+").flatMap((k, i) => (i ? [h("span", { class: "plus" }, "+"), h("kbd", {}, k)] : [h("kbd", {}, k)]));
}

export function togglePopover(button: HTMLElement, panel: HTMLElement): void {
  const open = panel.hidden;
  panel.hidden = !open;
  button.setAttribute("aria-expanded", String(open));
  if (!open) return;
  const close = (e: Event) => {
    if (e instanceof KeyboardEvent && e.key !== "Escape") return;
    if (e instanceof MouseEvent && (panel.contains(e.target as Node) || button.contains(e.target as Node))) return;
    panel.hidden = true;
    button.setAttribute("aria-expanded", "false");
    document.removeEventListener("keydown", close, true);
    document.removeEventListener("mousedown", close, true);
    if (e instanceof KeyboardEvent) button.focus();
  };
  document.addEventListener("keydown", close, true);
  document.addEventListener("mousedown", close, true);
}

export function slug(text: string): string {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .replace(/ł/g, "l")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

export function download(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = h("a", { href: url, download: filename, class: "visually-hidden" });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function nextPaint(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(() => setTimeout(resolve, 0));
    else setTimeout(resolve, 16);
  });
}
