const HOME_TURTLE: TurtleState = {
  position: [0, 0, 0],
  heading: [0, 1, 0],
  right: [1, 0, 0],
  up: [0, 0, 1],
  penDown: true,
  color: "#16866a",
  width: 3,
};

function fmt(n: number): string {
  return String(n).replace("-", "−");
}

function interleave(parts: HTMLElement[]): Node[] {
  const out: Node[] = [];
  parts.forEach((p, i) => {
    if (i) out.push(h("span", { class: "sep", "aria-hidden": "true" }, "·"));
    out.push(p);
  });
  return out;
}

export function kbd(keys: string): HTMLElement[] {
  return keys.split("+").flatMap((k, i) => (i ? [h("span", { class: "plus" }, "+"), h("kbd", {}, k)] : [h("kbd", {}, k)]));
}

export function togglePopover(button: HTMLElement, panel: HTMLElement): void {
  const open = panel.hidden;
  panel.hidden = !open;
  button.setAttribute("aria-expanded", String(open));
  if (!open) return;
  const close = (e: Event) => {
    if (e instanceof KeyboardEvent && e.key !== "Escape") return;
    if (e instanceof MouseEvent && (panel.contains(e.target as Node) || button.contains(e.target as Node))) return;
    panel.hidden = true;
    button.setAttribute("aria-expanded", "false");
    document.removeEventListener("keydown", close, true);
    document.removeEventListener("mousedown", close, true);
    if (e instanceof KeyboardEvent) button.focus();
  };
  document.addEventListener("keydown", close, true);
  document.addEventListener("mousedown", close, true);
}

export function slug(text: string): string {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .replace(/ł/g, "l")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

export function download(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = h("a", { href: url, download: filename, class: "visually-hidden" });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function nextPaint(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(() => setTimeout(resolve, 0));
    else setTimeout(resolve, 16);
  });
}
