import { h } from "./dom";
import { icon } from "./icons";

export interface ToastOptions {
  action?: string;
  onAction?: () => void;
  /** Extra selectable text, such as a link to copy by hand. */
  detail?: string;
}

export interface ListItem {
  label: string;
  detail?: string;
  onPick: () => void;
}

/** Non-blocking notices in a polite live region, with an optional action. */
export class Toaster {
  readonly element: HTMLElement;
  private timer: ReturnType<typeof setTimeout> | null = null;

  constructor() {
    this.element = h("div", { class: "toaster", role: "status", "aria-live": "polite" });
  }

  get text(): string {
    return this.element.textContent ?? "";
  }

  show(message: string, options: ToastOptions = {}): void {
    const close = h("button", { type: "button", class: "toast-close", "aria-label": "Zamknij komunikat", onclick: () => this.clear() }, icon("cross"));
    const body = h("div", { class: "toast" }, h("p", { class: "toast-text" }, message));
    if (options.detail)
      body.append(h("input", { class: "toast-detail", type: "text", readonly: true, value: options.detail, "aria-label": "Link", onfocus: (e: Event) => (e.target as HTMLInputElement).select() }));
    if (options.action && options.onAction) {
      const run = options.onAction;
      body.append(
        h("button", { type: "button", class: "btn btn-quiet toast-action", onclick: () => (this.clear(), run()) }, options.action),
      );
    }
    body.append(close);
    this.element.replaceChildren(body);
    this.arm(options.detail || options.action ? 12000 : 6000);
  }

  list(title: string, items: ListItem[]): void {
    const close = h("button", { type: "button", class: "toast-close", "aria-label": "Zamknij listę", onclick: () => this.clear() }, icon("cross"));
    const list = h(
      "ul",
      { class: "toast-list" },
      ...items.map((it) =>
        h(
          "li",
          {},
          h(
            "button",
            { type: "button", class: "toast-pick", onclick: () => (this.clear(), it.onPick()) },
            h("span", { class: "toast-pick-label" }, it.label),
            it.detail ? h("code", { class: "toast-pick-detail" }, it.detail) : null,
          ),
        ),
      ),
    );
    this.element.replaceChildren(h("div", { class: "toast toast-wide" }, h("p", { class: "toast-text" }, title), list, close));
    this.arm(0);
    (list.querySelector("button") as HTMLButtonElement | null)?.focus();
  }

  clear(): void {
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    this.element.replaceChildren();
  }

  private arm(ms: number) {
    if (this.timer) clearTimeout(this.timer);
    this.timer = ms ? setTimeout(() => this.clear(), ms) : null;
  }
}
