import type { Mode } from "../lang";

const toB64url = (bytes: Uint8Array) => {
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};
const fromB64url = (text: string) => {
  const b64 = text.replace(/-/g, "+").replace(/_/g, "/");
  const bin = atob(b64 + "===".slice((b64.length + 3) % 4));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
};

async function pipe(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const out = new Blob([bytes as BlobPart]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(out).arrayBuffer());
}

/** Encode a program for a URL: "z" + deflated base64url when the browser can compress, else "b" + base64url. */
export async function encodeProgram(source: string): Promise<string> {
  const raw = new TextEncoder().encode(source);
  if (typeof CompressionStream === "function") {
    try {
      return "z" + toB64url(await pipe(raw, new CompressionStream("deflate-raw")));
    } catch {
      // fall through to the plain form
    }
  }
  return "b" + toB64url(raw);
}

export async function decodeProgram(code: string): Promise<string | null> {
  try {
    const kind = code[0];
    const bytes = fromB64url(code.slice(1));
    if (kind === "b") return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    if (kind === "z" && typeof DecompressionStream === "function")
      return new TextDecoder("utf-8", { fatal: true }).decode(await pipe(bytes, new DecompressionStream("deflate-raw")));
    return null;
  } catch {
    return null;
  }
}

/** The hash route that opens and runs a program. */
export async function programHash(source: string, mode: Mode): Promise<string> {
  return `#/program?tryb=${mode}&kod=${await encodeProgram(source)}`;
}

/** An absolute permalink for the current page location. */
export async function permalink(source: string, mode: Mode): Promise<string> {
  const base = location.href.replace(/#.*$/, "");
  return base + (await programHash(source, mode));
}
