import { run, type Mode, type RunResult } from "../lang";
import { h } from "../ui/dom";
import { brandMark } from "../ui/icons";
import { StudioPage } from "../ui/studio-page";
import { createThemeToggle } from "../ui/theme";
import { Toaster } from "../ui/toast";
import { href, parseRoute, type Route } from "./router";
import { browserScheduler, type Scheduler } from "./scheduler";
import { browserStore, type KeyValueStore } from "./store";

export const VERSION = "1.0.0";

export interface MountOptions {
  scheduler?: Scheduler;
  store?: KeyValueStore;
}

export interface MountedApp {
  readonly studio: StudioPage;
  readonly toast: Toaster;
  /** Resolves when the current route has finished loading (permalinks are async). */
  settled(): Promise<void>;
  destroy(): void;
}

export interface LogomocjaHook {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

const NAV: { route: Route["name"][]; label: string; href: string }[] = [
  { route: ["studio", "program"], label: "Studio", href: href.studio },
  { route: ["examples"], label: "Przykłady", href: href.examples },
  { route: ["challenges", "challenge"], label: "Wyzwania", href: href.challenges },
  { route: ["help"], label: "Pomoc", href: href.help() },
];

export function mountApp(root: HTMLElement, options: MountOptions = {}): MountedApp {
  const store = options.store ?? browserStore();
  const scheduler = options.scheduler ?? browserScheduler();
  const toast = new Toaster();
  let pending: Promise<void> = Promise.resolve();

  const challengeSlot = h("div", { class: "challenge-slot" });
  const studio = new StudioPage({ store, scheduler, toast, challengeSlot, onExitChallenge: () => go(href.challenges) });
  const pageHost = h("div", { class: "page-host" });

  const navLinks = NAV.map((n) => h("a", { href: n.href, class: "nav-link", "data-route": n.route.join(" ") }, n.label));
  const theme = createThemeToggle(store, () => studio.onThemeChange());
  const header = h(
    "header",
    { class: "band" },
    h("a", { class: "brand", href: href.studio, "aria-label": "Logomocja: studio" }, brandMark(), h("span", { class: "brand-name" }, "Logomocja")),
    h("nav", { class: "nav", "aria-label": "Główna" }, ...navLinks),
    theme,
  );
  const main = h("main", { class: "main", id: "main", tabindex: "-1" }, studio.element, pageHost);
  root.classList.add("app");
  root.replaceChildren(h("a", { class: "skip-link", href: "#main", onclick: (e: Event) => (e.preventDefault(), main.focus()) }, "Przejdź do treści"), header, main, toast.element);

  function go(target: string) {
    if (location.hash === target) render();
    else location.hash = target;
  }

  let current: Route = { name: "studio" };
  function render() {
    const route = parseRoute(location.hash);
    current = route;
    for (const link of navLinks) {
      const on = (link.dataset.route ?? "").split(" ").includes(route.name);
      if (on) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    }
    const onStudio = route.name === "studio" || route.name === "program" || route.name === "challenge";
    studio.element.hidden = !onStudio;
    pageHost.hidden = onStudio;
    if (route.name !== "challenge" && studio.inChallenge) studio.leaveChallenge(false);
    if (route.name === "program") pending = openPermalink(route);
    else if (!onStudio) pageHost.replaceChildren(renderPage(route));
    document.title = route.name === "help" ? "Pomoc · Logomocja" : route.name === "examples" ? "Przykłady · Logomocja" : route.name.startsWith("challenge") ? "Wyzwania · Logomocja" : "Logomocja";
  }

  function renderPage(route: Route): HTMLElement {
    return h("section", { class: "page" }, h("h1", {}, route.name));
  }

  async function openPermalink(route: Extract<Route, { name: "program" }>) {
    const { decodeProgram } = await import("./share");
    const mode: Mode = route.mode === "3d" ? "3d" : "2d";
    const source = route.code ? await decodeProgram(route.code) : null;
    history.replaceState(null, "", href.studio);
    current = { name: "studio" };
    if (source === null) {
      toast.show("Ten link jest uszkodzony: nie da się z niego odczytać programu.");
      return;
    }
    studio.load(source, mode, "Program z linku");
    await studio.runInstantly();
  }

  const onKey = (e: KeyboardEvent) => {
    if (!studio.element.hidden) studio.handleShortcut(e);
  };
  document.addEventListener("keydown", onKey, true);
  window.addEventListener("hashchange", render);
  render();

  const hook: LogomocjaHook = {
    version: VERSION,
    run: (source, mode) => run(source, mode),
    async open(source, mode) {
      if (current.name !== "studio") go(href.studio);
      studio.load(source, mode, "Program otwarty z zewnątrz");
      return studio.runInstantly();
    },
  };
  (window as unknown as { logomocja: LogomocjaHook }).logomocja = hook;

  return {
    studio,
    toast,
    settled: () => pending,
    destroy() {
      document.removeEventListener("keydown", onKey, true);
      window.removeEventListener("hashchange", render);
      studio.destroy();
      root.replaceChildren();
    },
  };
}
