input.command:
cat > /work/src/styles/base.css <<'EOF'
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100dvh;
  background: var(--ground);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--text-md);
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

h1,
h2,
h3,
h4,
p {
  margin: 0;
}

h1,
h2,
h3 {
  text-wrap: balance;
  line-height: 1.2;
}

a {
  color: var(--fam-control);
  text-underline-offset: 0.18em;
  text-decoration-thickness: 1px;
}

a:hover {
  text-decoration-thickness: 2px;
}

::selection {
  background: var(--select);
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 3px;
}

* {
  scrollbar-color: var(--rule-2) transparent;
  scrollbar-width: thin;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-thumb {
  background: var(--rule-2);
  border-radius: 10px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-track {
  background: transparent;
}

[hidden] {
  display: none !important;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: var(--s3);
  top: -60px;
  z-index: 50;
  padding: var(--s2) var(--s3);
  background: var(--plate);
  color: var(--plate-ink);
  border-radius: var(--radius);
  text-decoration: none;
}
.skip-link:focus {
  top: var(--s2);
}

kbd {
  display: inline-block;
  min-width: 1.6em;
  padding: 0 0.4em;
  border: 1px solid var(--rule-2);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--paper);
  font-family: var(--font-code);
  font-size: 0.8em;
  line-height: 1.5;
  text-align: center;
  color: var(--ink);
  white-space: nowrap;
}
.plus {
  margin: 0 0.15em;
  color: var(--ink-3);
}

.icon {
  flex: none;
  width: 20px;
  height: 20px;
}

/* ---------------------------------------------------------------- band */

.app {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

.band {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: var(--s4);
  height: var(--band-h);
  padding: 0 var(--s4);
  padding-left: max(var(--s4), env(safe-area-inset-left));
  padding-right: max(var(--s4), env(safe-area-inset-right));
  background: var(--band);
  color: var(--band-ink);
  border-bottom: 1px solid var(--band-rule);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: var(--s2);
  color: inherit;
  text-decoration: none;
  font-weight: 750;
  font-stretch: var(--narrow);
  font-size: var(--text-xl);
  letter-spacing: -0.01em;
}
.brand:focus-visible,
.nav-link:focus-visible,
.theme-toggle:focus-visible {
  outline-color: var(--band-ink);
}
.brand-mark {
  width: 24px;
  height: 24px;
}

.nav {
  display: flex;
  gap: var(--s1);
  margin-right: auto;
  margin-left: var(--s3);
}

.nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 var(--s3);
  border-radius: var(--radius);
  color: var(--band-ink-2);
  text-decoration: none;
  font-weight: 560;
  transition: background-color var(--fast) var(--ease), color var(--fast) var(--ease);
}
.nav-link:hover {
  background: rgb(255 255 255 / 0.1);
  color: var(--band-ink);
}
.nav-link[aria-current="page"] {
  color: var(--band-ink);
  background: rgb(0 0 0 / 0.16);
}
.nav-link[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: var(--s3);
  right: var(--s3);
  bottom: 4px;
  height: 2px;
  border-radius: 2px;
  background: var(--band-ink);
}

.theme-toggle {
  display: inline-flex;
  align-items: center;
  gap: var(--s2);
  height: 36px;
  padding: 0 var(--s3);
  border: 1px solid rgb(255 255 255 / 0.35);
  border-radius: var(--radius);
  background: transparent;
  color: var(--band-ink);
  cursor: pointer;
  font-weight: 560;
  transition: background-color var(--fast) var(--ease);
}
.theme-toggle:hover {
  background: rgb(255 255 255 / 0.12);
}

.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.main:focus {
  outline: none;
}

/* ---------------------------------------------------------------- buttons */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--s2);
  min-height: 36px;
  padding: 0 var(--s3);
  border: 1px solid var(--rule-2);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
  font-weight: 560;
  font-size: var(--text-md);
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition: background-color var(--fast) var(--ease), border-color var(--fast) var(--ease), color var(--fast) var(--ease);
}
.btn:hover:not(:disabled) {
  background: var(--paper-2);
  border-color: var(--ink-3);
}
.btn:active:not(:disabled) {
  background: var(--paper-3);
}
.btn:disabled {
  cursor: not-allowed;
  color: var(--ink-3);
  border-color: var(--rule);
  background: var(--paper);
  opacity: 0.7;
}

.btn-plate {
  background: var(--plate);
  border-color: var(--plate);
  color: var(--plate-ink);
}
.btn-plate .icon {
  color: var(--spot-green);
}
:root[data-theme="dark"] .btn-plate .icon {
  color: #0e6e55;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .btn-plate .icon {
    color: #0e6e55;
  }
}
.btn-plate:hover:not(:disabled) {
  background: var(--plate-hover);
  border-color: var(--plate-hover);
}
.btn-plate:active:not(:disabled) {
  background: var(--plate-hover);
}

.btn-quiet {
  border-color: transparent;
  background: transparent;
}
.btn-quiet:hover:not(:disabled) {
  background: var(--paper-3);
  border-color: transparent;
}

.btn-icon {
  width: 36px;
  padding: 0;
}

/* ---------------------------------------------------------------- toast */

.toaster {
  position: fixed;
  left: 50%;
  bottom: max(var(--s4), env(safe-area-inset-bottom));
  z-index: 40;
  width: min(560px, calc(100vw - 2 * var(--s3)));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: var(--s2) var(--s3);
  padding: var(--s3) var(--s3) var(--s3) var(--s4);
  border-radius: var(--radius-lg);
  background: var(--plate);
  color: var(--plate-ink);
  box-shadow: var(--shadow-pop);
  animation: toast-in 200ms var(--ease);
}
.toast-text {
  grid-column: 1;
}
.toast-close {
  grid-column: 2;
  grid-row: 1;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.toast-close:hover {
  background: rgb(127 127 127 / 0.25);
}
.toast-action {
  grid-column: 1;
  justify-self: start;
  color: inherit;
  border-color: rgb(127 127 127 / 0.55);
}
.toast .toast-action:hover:not(:disabled) {
  background: rgb(127 127 127 / 0.25);
}
.toast-detail {
  grid-column: 1 / -1;
  width: 100%;
  padding: var(--s2);
  border: 1px solid rgb(127 127 127 / 0.5);
  border-radius: var(--radius);
  background: transparent;
  font-family: var(--font-code);
  font-size: var(--text-xs);
}
.toast :focus-visible {
  outline-color: var(--plate-ink);
}
.toast-list {
  grid-column: 1 / -1;
  margin: 0;
  padding: 0;
  list-style: none;
  max-height: 50vh;
  overflow: auto;
}
.toast-pick {
  display: grid;
  width: 100%;
  gap: 2px;
  padding: var(--s2);
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.toast-pick:hover {
  background: rgb(127 127 127 / 0.22);
}
.toast-pick-detail {
  font-family: var(--font-code);
  font-size: var(--text-xs);
  opacity: 0.8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    transition-duration: 1ms !important;
  }
}

@media (max-width: 720px) {
  .band {
    gap: var(--s2);
    height: auto;
    min-height: var(--band-h);
    flex-wrap: wrap;
    padding-top: var(--s2);
    padding-bottom: 0;
  }
  .brand {
    font-size: var(--text-lg);
  }
  .theme-label {
    display: none;
  }
  .theme-toggle {
    margin-left: auto;
    padding: 0 var(--s2);
  }
  .nav {
    order: 3;
    width: 100%;
    margin: 0 calc(-1 * var(--s2));
    overflow-x: auto;
  }
  .nav-link {
    height: 40px;
  }
}
EOF
echo ok

