  line-height: 1.5;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

h1,
h2,
h3,
h4,
p {
  margin: 0;
}

h1,
h2,
h3 {
  text-wrap: balance;
  line-height: 1.2;
}

a {
  color: var(--fam-control);
  text-underline-offset: 0.18em;
  text-decoration-thickness: 1px;
}

a:hover {
  text-decoration-thickness: 2px;
}

::selection {
  background: var(--select);
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 3px;
}

* {
  scrollbar-color: var(--rule-2) transparent;
  scrollbar-width: thin;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-thumb {
  background: var(--rule-2);
  border-radius: 10px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-track {
  background: transparent;
}

[hidden] {
  display: none !important;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: var(--s3);
  top: -60px;
  z-index: 50;
  padding: var(--s2) var(--s3);
  background: var(--plate);
  color: var(--plate-ink);
  border-radius: var(--radius);
  text-decoration: none;
}
.skip-link:focus {
  top: var(--s2);
}

kbd {
  display: inline-block;
  min-width: 1.6em;
  padding: 0 0.4em;
  border: 1px solid var(--rule-2);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--paper);
  font-family: var(--font-code);
  font-size: 0.8em;
  line-height: 1.5;
  text-align: center;
  color: var(--ink);
  white-space: nowrap;
}
.plus {
  margin: 0 0.15em;
  color: var(--ink-3);
}

.icon {
  flex: none;
  width: 20px;
  height: 20px;
}

/* ---------------------------------------------------------------- band */

.app {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

.band {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: var(--s4);
  height: var(--band-h);
  padding: 0 var(--s4);
  padding-left: max(var(--s4), env(safe-area-inset-left));
  padding-right: max(var(--s4), env(safe-area-inset-right));
  background: var(--band);
  color: var(--band-ink);
  border-bottom: 1px solid var(--band-rule);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: var(--s2);
  color: inherit;
  text-decoration: none;
  font-weight: 750;
  font-stretch: var(--narrow);
  font-size: var(--text-xl);
  letter-spacing: -0.01em;
}
.brand:focus-visible,
.nav-link:focus-visible,
.theme-toggle:focus-visible {
  outline-color: var(--band-ink);
}
.brand-mark {
  width: 24px;
  height: 24px;
}

.nav {
  display: flex;
  gap: var(--s1);
  margin-right: auto;
  margin-left: var(--s3);
}

.nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 var(--s3);
  border-radius: var(--radius);
  color: var(--band-ink-2);
  text-decoration: none;
  font-weight: 560;
  transition: background-color var(--fast) var(--ease), color var(--fast) var(--ease);
}
.nav-link:hover {
  background: rgb(255 255 255 / 0.1);
  color: var(--band-ink);
}
.nav-link[aria-current="page"] {
  color: var(--band-ink);
  background: rgb(0 0 0 / 0.16);
}
.nav-link[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: var(--s3);
  right: var(--s3);
  bottom: 4px;
  height: 2px;
  border-radius: 2px;
  background: var(--band-ink);
}

.theme-toggle {
  display: inline-flex;
  align-items: center;
  gap: var(--s2);
  height: 36px;
  padding: 0 var(--s3);
  border: 1px solid rgb(255 255 255 / 0.35);
  border-radius: var(--radius);
  background: transparent;
  color: var(--band-ink);
  cursor: pointer;
  font-weight: 560;
  transition: background-color var(--fast) var(--ease);
}
.theme-toggle:hover {
  background: rgb(255 255 255 / 0.12);
}

.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.main:focus {
  outline: none;
}

/* ---------------------------------------------------------------- buttons */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--s2);
  min-height: 36px;
  padding: 0 var(--s3);
  border: 1px solid var(--rule-2);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
  font-weight: 560;
  font-size: var(--text-md);
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition: background-color var(--fast) var(--ease), border-color var(--fast) var(--ease), color var(--fast) var(--ease);
}
.btn:hover:not(:disabled) {
  background: var(--paper-2);
  border-color: var(--ink-3);
}
.btn:active:not(:disabled) {
  background: var(--paper-3);
}
.btn:disabled {
  cursor: not-allowed;
  color: var(--ink-3);
  border-color: var(--rule);
  background: var(--paper);
  opacity: 0.7;
}

.btn-plate {
  background: var(--plate);
  border-color: var(--plate);
  color: var(--plate-ink);
}
.btn-plate .icon {
  color: var(--spot-green);
}
:root[data-theme="dark"] .btn-plate .icon {
  color: #0e6e55;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .btn-plate .icon {
    color: #0e6e55;
  }
}
.btn-plate:hover:not(:disabled) {
  background: var(--plate-hover);
  border-color: var(--plate-hover);
}
.btn-plate:active:not(:disabled) {
  background: var(--plate-hover);
}

.btn-quiet {
  border-color: transparent;
  background: transparent;
}
.btn-quiet:hover:not(:disabled) {
  background: var(--paper-3);
  border-color: transparent;
}

.btn-icon {
  width: 36px;
  padding: 0;
}

/* ---------------------------------------------------------------- toast */

.toaster {
  position: fixed;
  left: 50%;
  bottom: max(var(--s4), env(safe-area-inset-bottom));
  z-index: 40;
  width: min(560px, calc(100vw - 2 * var(--s3)));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: var(--s2) var(--s3);
  padding: var(--s3) var(--s3) var(--s3) var(--s4);
  border-radius: var(--radius-lg);
  background: var(--plate);
  color: var(--plate-ink);
  box-shadow: var(--shadow-pop);
  animation: toast-in 200ms var(--ease);
}
.toast-text {
  grid-column: 1;
}
.toast-close {
  grid-column: 2;
  grid-row: 1;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.toast-close:hover {
  background: rgb(127 127 127 / 0.25);
}
.toast-action {
  grid-column: 1;
  justify-self: start;
  color: inherit;
  border-color: rgb(127 127 127 / 0.55);
}
.toast .toast-action:hover:not(:disabled) {
  background: rgb(127 127 127 / 0.25);
}
.toast-detail {
  grid-column: 1 / -1;
  width: 100%;
  padding: var(--s2);
  border: 1px solid rgb(127 127 127 / 0.5);
  border-radius: var(--radius);
  background: transparent;
  font-family: var(--font-code);
  font-size: var(--text-xs);
}
.toast :focus-visible {
  outline-color: var(--plate-ink);
}
.toast-list {
  grid-column: 1 / -1;
  margin: 0;
  padding: 0;
  list-style: none;
  max-height: 50vh;
  overflow: auto;
}
.toast-pick {
  display: grid;
  width: 100%;
  gap: 2px;
  padding: var(--s2);
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.toast-pick:hover {
  background: rgb(127 127 127 / 0.22);
}
.toast-pick-detail {
  font-family: var(--font-code);
  font-size: var(--text-xs);
  opacity: 0.8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    transition-duration: 1ms !important;
  }
}

@media (max-width: 720px) {
  .band {
    gap: var(--s2);
    height: auto;
    min-height: var(--band-h);
    flex-wrap: wrap;
    padding-top: var(--s2);
    padding-bottom: 0;
  }
  .brand {
    font-size: var(--text-lg);
  }
  .theme-label {
    display: none;
  }
  .theme-toggle {
    margin-left: auto;
    padding: 0 var(--s2);
  }
  .nav {
    order: 3;
    width: 100%;
    margin: 0 calc(-1 * var(--s2));
    overflow-x: auto;
  }
  .nav-link {
    height: 40px;
  }
}
EOF
echo ok

input.command:
cat > /work/src/styles/studio.css <<'EOF'
/* ---------------------------------------------------------------- layout */

.studio {
  display: grid;
  grid-template-columns: minmax(360px, 5fr) minmax(0, 7fr);
  gap: var(--s3);
  padding: var(--s3);
  height: calc(100dvh - var(--band-h));
  min-height: 560px;
}

.studio-code {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.doc-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--s2) var(--s3);
  padding: var(--s2) var(--s3);
  border-bottom: 1px solid var(--rule);
}

.doc-title {
  flex: 1 1 8rem;
  min-width: 0;
  font-size: var(--text-lg);
  font-weight: 650;
  font-stretch: var(--narrow);
  letter-spacing: -0.005em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.doc-actions {
  display: flex;
  gap: 2px;
  margin-left: auto;
}
.doc-actions .btn {
  min-height: 32px;
  padding: 0 var(--s2);
  font-size: var(--text-sm);
  color: var(--ink-2);
}
.doc-actions .btn:hover:not(:disabled) {
  color: var(--ink);
}

/* Segmented 2D / 3D switch */
.mode-switch {
  display: inline-flex;
  padding: 2px;
  border: 1px solid var(--rule-2);
  border-radius: calc(var(--radius) + 2px);
  background: var(--paper-2);
}
.seg {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  min-height: 32px;
  padding: 0 var(--s3);
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--ink-2);
  cursor: pointer;
  line-height: 32px;
  transition: background-color var(--fast) var(--ease), color var(--fast) var(--ease);
}
.seg-main {
  font-weight: 700;
}
.seg-sub {
  font-size: var(--text-xs);
  font-stretch: var(--narrow);
}
.seg:hover:not(:disabled) {
  color: var(--ink);
  background: var(--paper-3);
}
.seg[aria-pressed="true"] {
  background: var(--ok-bg);
  color: var(--fam-move);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fam-move) 35%, transparent);
}
.seg:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

/* Run toolbar */
.runbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--s2);
  padding: var(--s2) var(--s3);
  border-bottom: 1px solid var(--rule);
  background: var(--paper-2);
}
.runbar .btn-plate {
  padding: 0 var(--s4) 0 var(--s3);
}
.speed {
  display: flex;
  align-items: center;
  gap: var(--s2);
  margin-left: auto;
  font-size: var(--text-sm);
  color: var(--ink-2);
}
.speed label {
  font-weight: 560;
}
.speed input[type="range"] {
  width: 120px;
  accent-color: var(--spot-green);
}
.speed-value {
  min-width: 6.5em;
  font-stretch: var(--narrow);
  font-weight: 600;
  color: var(--ink);
}

.popover-anchor {
  position: relative;
}
.popover {
  position: absolute;
  right: 0;
  top: calc(100% + 6px);
  z-index: 30;
  width: max-content;
  max-width: min(340px, 86vw);
  padding: var(--s3) var(--s4);
  border-radius: var(--radius-lg);
  background: var(--paper);
  color: var(--ink);
  box-shadow: var(--shadow-pop);
}
.popover-title {
  font-weight: 650;
  margin-bottom: var(--s2);
}
.popover-note {
  margin-top: var(--s3);
  font-size: var(--text-sm);
  color: var(--ink-2);
}
.keys {
  display: grid;
  grid-template-columns: auto auto;
  gap: var(--s2) var(--s4);
  margin: 0;
  font-size: var(--text-sm);
}
.keys dt {
  color: var(--ink-2);
}
.keys dd {
  margin: 0;
}

/* ---------------------------------------------------------------- editor */

.editor-host {
  flex: 1;
  min-height: 0;
  display: flex;
}
.editor-host .cm-editor {
  flex: 1;
  min-width: 0;
  height: 100%;
  background: var(--paper);
  color: var(--ink);
  font-size: 14.5px;
}
.editor-host .cm-editor.cm-focused {
  outline: none;
}
.editor-host:focus-within {
  box-shadow: inset 0 0 0 2px var(--focus);
}
.cm-scroller {
  font-family: var(--font-code) !important;
  line-height: 1.65 !important;
  font-variant-ligatures: none;
}
.cm-content {
  padding: var(--s3) 0 var(--s6) !important;
  caret-color: var(--ink);
}
.cm-line {
  padding: 0 var(--s4) 0 var(--s3) !important;
}
.cm-gutters {
  background: var(--paper-2) !important;
  border-right: 1px solid var(--rule) !important;
  color: var(--ink-3) !important;
}
.cm-lineNumbers .cm-gutterElement {
  min-width: 3ch;
  padding: 0 var(--s2) 0 var(--s3) !important;
  font-size: 12.5px;
}
.cm-activeLine {
  background: color-mix(in srgb, var(--paper-3) 55%, transparent) !important;
}
.cm-activeLineGutter {
  background: var(--paper-3) !important;
  color: var(--ink) !important;
}
.cm-cursor {
  border-left: 2px solid var(--ink) !important;
}
.cm-selectionBackground,
.cm-focused .cm-selectionBackground {
  background: var(--select) !important;
}
.cm-matchingBracket {
  background: color-mix(in srgb, var(--spot-blue) 18%, transparent) !important;
  outline: 1px solid color-mix(in srgb, var(--spot-blue) 50%, transparent);
  color: inherit !important;
}
.cm-placeholder {
  color: var(--ink-3) !important;
}

.tok-kw-move {
  color: var(--fam-move);
  font-weight: 650;
}
.tok-kw-turn {
  color: var(--fam-turn);
  font-weight: 650;
}
.tok-kw-pen {
  color: var(--fam-pen);
  font-weight: 650;
}
.tok-kw-control {
  color: var(--fam-control);
  font-weight: 650;
}
.tok-kw-define {
  color: var(--fam-define);
  font-weight: 650;
}
.tok-proc {
  color: var(--fam-define);
  font-style: italic;
}
.tok-name {
  color: var(--tok-name);
  font-style: italic;
}
.tok-num {
  color: var(--tok-num);
}
.tok-str {
  color: var(--fam-pen);
  text-decoration: underline;
  text-decoration-color: var(--swatch, currentColor);
  text-decoration-thickness: 4px;
  text-underline-offset: 4px;
  text-decoration-skip-ink: none;
}
.tok-comment {
  color: var(--tok-comment);
  font-style: italic;
}
.tok-bracket,
.tok-paren {
  color: var(--tok-punct);
  font-weight: 700;
}
.tok-op {
  color: var(--tok-punct);
}
.tok-invalid {
  color: var(--error);
}

.cm-logo-exec-line {
  background: var(--exec-line) !important;
}
.cm-logo-exec {
  background: var(--exec-mark);
  border-radius: 2px;
  box-shadow: 0 0 0 1px var(--exec-mark);
}
.cm-logo-error-line {
  background: var(--error-bg) !important;
}
.cm-logo-error {
  text-decoration: underline wavy var(--error);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
  text-decoration-skip-ink: none;
}
.cm-logo-message {
  position: relative;
  margin: 6px var(--s4) 8px calc(var(--s3) + min(var(--col, 0) * 1ch, 50%));
  padding: 6px 10px;
  max-width: 56ch;
  width: fit-content;
  border: 1px solid var(--error-rule);
  border-radius: var(--radius);
  background: var(--error-bg);
  color: var(--error);
  font-family: var(--font-ui);
  font-size: var(--text-sm);
  font-weight: 560;
  line-height: 1.4;
  white-space: normal;
}
.cm-logo-message::before {
  content: "";
  position: absolute;
  top: -6px;
  left: 6px;
  width: 10px;
  height: 10px;
  background: var(--error-bg);
  border-left: 1px solid var(--error-rule);
  border-top: 1px solid var(--error-rule);
  transform: rotate(45deg);
}

/* ---------------------------------------------------------------- status */

.error-box {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--s1) var(--s3);
  padding: var(--s2) var(--s3);
  border-top: 1px solid var(--error-rule);
  background: var(--error-bg);
  color: var(--error);
  font-size: var(--text-sm);
}
.error-where {
  padding: 2px 6px;
  border: 1px solid var(--error-rule);
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font-weight: 700;
  font-stretch: var(--narrow);
  cursor: pointer;
}
.error-where:hover {
  background: color-mix(in srgb, var(--error) 10%, transparent);
}
.error-message {
  flex: 1 1 20ch;
  color: var(--ink);
}

.status {
  padding: var(--s2) var(--s3);
  border-top: 1px solid var(--rule);
  font-size: var(--text-sm);
  color: var(--ink-2);
  min-height: 2.5em;
}
.status[data-state="running"]::before,
.status[data-state="paused"]::before,
.status[data-state="done"]::before,
.status[data-state="error"]::before,
.status[data-state="stopped"]::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: var(--s2);
  border-radius: 50%;
  vertical-align: 1px;
  background: var(--ink-3);
}
.status[data-state="running"]::before {
  background: var(--spot-green);
}
.status[data-state="paused"]::before,
.status[data-state="stopped"]::before {
  background: var(--spot-copper);
}
.status[data-state="done"]::before {
  background: var(--fam-move);
}
.status[data-state="error"]::before {
  background: var(--error);
}

/* ---------------------------------------------------------------- the sheet */

.studio-sheet {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  padding: 20px 20px 10px;
}

.sheet {
  position: relative;
  flex: 1;
  min-height: 0;
  background: var(--sheet);
  border-radius: 1px;
  box-shadow: 0 1px 2px rgb(23 34 30 / 0.12), 0 6px 18px rgb(23 34 30 / 0.08);
}
/* Crop marks just outside the trim, as on a printed sheet. */
.sheet::after {
  --c: var(--ink-3);
  content: "";
  position: absolute;
  inset: -16px;
  pointer-events: none;
  background:
    linear-gradient(var(--c), var(--c)) left 0 top 16px / 11px 1px no-repeat,
    linear-gradient(var(--c), var(--c)) left 16px top 0 / 1px 11px no-repeat,
    linear-gradient(var(--c), var(--c)) right 0 top 16px / 11px 1px no-repeat,
    linear-gradient(var(--c), var(--c)) right 16px top 0 / 1px 11px no-repeat,
    linear-gradient(var(--c), var(--c)) left 0 bottom 16px / 11px 1px no-repeat,
    linear-gradient(var(--c), var(--c)) left 16px bottom 0 / 1px 11px no-repeat,
    linear-gradient(var(--c), var(--c)) right 0 bottom 16px / 11px 1px no-repeat,
    linear-gradient(var(--c), var(--c)) right 16px bottom 0 / 1px 11px no-repeat;
}

.sheet-canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
