const button = (root: HTMLElement, action: string) => root.querySelector<HTMLButtonElement>(`[data-action="${action}"]`)!;
const status = (root: HTMLElement) => root.querySelector(".status")!.textContent ?? "";
const segmentCount = (root: HTMLElement) => root.querySelector('[data-role="segment-count"]')!.textContent ?? "";
const execLine = (root: HTMLElement) => {
  const lines = [...root.querySelectorAll(".cm-content .cm-line")];
  return lines.findIndex((l) => l.classList.contains("cm-logo-exec-line")) + 1;
};

describe("execution controls", () => {
  test("Uruchom animates the run to the end at the chosen speed", async () => {
    const { root, clock } = boot();
    await (window as any).logomocja.open("powtorz 4 [np 50 pw 90]", "2d");
    button(root, "reset").click();
    expect(segmentCount(root)).toBe("0 odcinków");
    button(root, "run").click();
    expect(status(root)).toContain("rysuje");
    clock.advance(60_000);
    expect(status(root)).toContain("Gotowe: 4 odcinki");
    expect(segmentCount(root)).toBe("4 odcinki");
  });

  test("Krok runs one command at a time and highlights its line; Pauza and Wznów hold and continue", async () => {
    const { root, clock } = boot();
    await (window as any).logomocja.open("np 10\npw 90\nnp 10\npw 90\nnp 10", "2d");
    button(root, "reset").click();
    button(root, "step").click();
    expect(execLine(root)).toBe(1);
    expect(segmentCount(root)).toBe("1 odcinek");
    button(root, "step").click();
    expect(execLine(root)).toBe(2);
    expect(status(root)).toContain("Pauza");

    const pause = button(root, "pause");
    expect(pause.textContent).toContain("Wznów");
    pause.click();
    clock.advance(60_000);
    expect(segmentCount(root)).toBe("3 odcinki");
    expect(execLine(root)).toBe(0);
  });

  test("Od nowa clears the sheet and the turtle goes home", async () => {
    const { root } = boot();
    await (window as any).logomocja.open("np 40 pw 90", "2d");
    expect(segmentCount(root)).toBe("1 odcinek");
    button(root, "reset").click();
    expect(segmentCount(root)).toBe("0 odcinków");
    expect(root.querySelector(".imprint-turtle")!.textContent).toContain("0, 0 · kierunek 0°");
  });
