import { highlightTokens } from "../lang/highlight";
import { h } from "./dom";

/** A highlighted, read-only code block using the editor's token classes. */
export function codeBlock(source: string, label?: string): HTMLElement {
  const code = h("code", {});
  let at = 0;
  for (const t of highlightTokens(source)) {
    if (t.from > at) code.append(source.slice(at, t.from));
    const span = h("span", { class: `tok-${t.cls}` }, source.slice(t.from, t.to));
    if (t.color) span.style.setProperty("--swatch", t.color);
    code.append(span);
    at = t.to;
  }
  if (at < source.length) code.append(source.slice(at));
  return h("pre", { class: "code", ...(label ? { "aria-label": label } : {}) }, code);
}
EOF
