import { EXAMPLES, type Example } from "../content/examples";
import { run } from "../lang";
import { renderStill } from "../views/view2d";
import { codeBlock } from "./code";
import { formatCount, h, plural } from "./dom";
import { icon } from "./icons";

const MODE_NAME = { "2d": "2D · płaszczyzna", "3d": "3D · przestrzeń" } as const;

/** The standard programs as a set of sheets, each with the same anatomy. */
export function examplesPage(onOpen: (example: Example) => void): HTMLElement {
  const card = (ex: Example) => {
    const result = run(ex.source, ex.mode);
    const n = result.segments.length;
    const thumb = renderStill({ segments: result.segments, turtle: null, tween: null, ghost: [] }, ex.mode === "2d" ? "top" : "iso", 280, 200, {
      dpr: Math.min(2, globalThis.devicePixelRatio || 1),
      padding: 18,
    });
    thumb.className = "thumb";
    thumb.setAttribute("role", "img");
    thumb.setAttribute("aria-label", `Podgląd rysunku: ${ex.name}`);
    const headingId = `ex-${ex.id}`;
    return h(
      "article",
      { class: "sheet-card", "data-example": ex.id, "aria-labelledby": headingId },
      h("div", { class: "sheet-card-thumb" }, thumb),
      h(
        "div",
        { class: "sheet-card-body" },
        h("h3", { class: "sheet-card-title", id: headingId }, ex.name),
        h("p", { class: "sheet-card-note" }, ex.description),
        h(
          "p",
          { class: "sheet-card-meta" },
          h("span", { class: `mode-chip mode-${ex.mode}` }, MODE_NAME[ex.mode]),
          h("span", {}, `${formatCount(n)} ${plural(n, "odcinek", "odcinki", "odcinków")}`),
        ),
        h("details", { class: "sheet-card-code" }, h("summary", {}, "Kod programu"), codeBlock(ex.source, `Kod: ${ex.name}`)),
        h(
          "button",
          { type: "button", class: "btn", "data-action": "open-example", onclick: () => onOpen(ex) },
          icon("play"),
          h("span", {}, "Otwórz w studiu"),
          h("span", { class: "visually-hidden" }, `: ${ex.name}`),
        ),
      ),
    );
  };
  const group = (mode: "2d" | "3d", title: string, lead: string) =>
    h(
      "section",
      { class: "sheet-group", "aria-labelledby": `group-${mode}` },
      h("h2", { id: `group-${mode}` }, title),
      h("p", { class: "lead" }, lead),
      h("div", { class: "sheet-grid" }, ...EXAMPLES.filter((e) => e.mode === mode).map(card)),
    );
  return h(
    "div",
    { class: "page page-examples" },
    h(
      "header",
      { class: "page-head" },
      h("h1", {}, "Przykłady"),
      h(
        "p",
        { class: "lead" },
        "Trzynaście programów do uruchomienia i przerobienia. Otwarcie przykładu nie kasuje Twojego szkicu: trafia on do kopii, skąd można go przywrócić.",
      ),
    ),
    group("2d", "Na płaszczyźnie", "Żółw chodzi po kartce: naprzód, wstecz, w prawo i w lewo."),
    group("3d", "W przestrzeni", "Żółw wzlatuje i przechyla się: góra, dół, przechyły w prawo i w lewo."),
  );
}
EOF
