import { describe, expect, test } from "bun:test";
import { checkAttempt } from "../src/challenges/checker";
import { run } from "../src/lang";

const SQUARE = run("powtorz 4 [np 100 pw 90]", "2d").segments;
const attempt = (src: string, mode: "2d" | "3d" = "2d") => ({ source: src, result: run(src, mode) });

describe("challenge checker", () => {
  test("the same shape passes however it was drawn: order, direction, split strokes, position, mirror", () => {
    for (const src of [
      "powtorz 4 [np 100 pw 90]",
      "powtorz 4 [np 100 lw 90]",
      "powtorz 4 [np 50 np 50 pw 90]",
      "pod np 37 pw 90 np 12 lw 90 opu powtorz 4 [np 100 pw 90]",
      "pw 90 powtorz 4 [np 100 pw 90]",
      "pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 ws 100",
    ]) {
      const r = checkAttempt(attempt(src), { expected: SQUARE });
      expect(r).toMatchObject({ pass: true });
    }
  });

  test("small rounding differences are tolerated", () => {
    expect(checkAttempt(attempt("powtorz 4 [np 100.2 pw 90]"), { expected: SQUARE }).pass).toBe(true);
  });

  test("a different size fails and says so", () => {
    const r = checkAttempt(attempt("powtorz 4 [np 120 pw 90]"), { expected: SQUARE });
    expect(r.pass).toBe(false);
    expect(r.reason).toContain("120 × 120");
    expect(r.reason).toContain("100 × 100");
  });

  test("missing or extra lines fail with a count", () => {
    const missing = checkAttempt(attempt("np 100 pw 90 np 100 pw 90 np 100"), { expected: SQUARE });
    expect(missing.pass).toBe(false);
    expect(missing.reason).toContain("Brakuje");
    const extra = checkAttempt(attempt("powtorz 4 [np 100 pw 90] pw 45 np 141.42"), { expected: SQUARE });
    expect(extra.pass).toBe(false);
    expect(extra.reason).toMatch(/nadmiarow|nie ma we wzorze/);
  });

  test("an empty drawing or a program error fails with the reason", () => {
    expect(checkAttempt(attempt("pod np 10"), { expected: SQUARE }).reason).toContain("Nic");
    const err = checkAttempt(attempt("np 100 skok"), { expected: SQUARE });
    expect(err.pass).toBe(false);
    expect(err.reason).toContain("wiersz 1");
  });

  test("colour is checked only when the challenge asks for it", () => {
    const red = attempt('kolor "#c1763d" powtorz 4 [np 100 pw 90]');
    expect(checkAttempt(red, { expected: SQUARE }).pass).toBe(true);
    const r = checkAttempt(red, { expected: SQUARE, checkColor: true });
    expect(r.pass).toBe(false);
    expect(r.reason).toContain("kolor");
  });

  test("a required command must appear in the program", () => {
    const r = checkAttempt(attempt("np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100"), {
      expected: SQUARE,
      requires: [{ keyword: "repeat", hint: "Użyj «powtórz»." }],
    });
    expect(r.pass).toBe(false);
    expect(r.reason).toContain("powtórz");
  });

  test("3D drawings are compared in space", () => {
    const expected = run("powtorz 4 [np 80 gora 90]", "3d").segments;
    expect(checkAttempt(attempt("powtorz 4 [np 80 dol 90]", "3d"), { expected, space: true }).pass).toBe(true);
    expect(checkAttempt(attempt("powtorz 4 [np 80 pw 90]", "3d"), { expected, space: true }).pass).toBe(false);
  });
});
EOF
