import type { Keyword } from "../lang/keywords";
import { keywordOf } from "../lang/keywords";
import type { RunResult, Segment, Vec3 } from "../lang";

export interface Requirement {
  keyword: Keyword;
  /** What to tell the learner when the keyword is missing. */
  hint: string;
}

export interface CheckOptions {
  expected: readonly Segment[];
  /** Compare colours as well as shape. */
  checkColor?: boolean;
  /** 3D: compare in space; otherwise rotations by right angles and mirror images also count. */
  space?: boolean;
  requires?: readonly Requirement[];
}

export interface CheckResult {
  pass: boolean;
  reason: string;
}

interface Line {
  a: Vec3;
  b: Vec3;
  color: string;
}

const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const addk = (a: Vec3, d: Vec3, k: number): Vec3 => [a[0] + d[0] * k, a[1] + d[1] * k, a[2] + d[2] * k];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const len = (a: Vec3) => Math.hypot(a[0], a[1], a[2]);
const dist = (a: Vec3, b: Vec3) => len(sub(a, b));

/** The drawing as maximal straight lines: collinear pieces that touch or overlap become one. */
function maximalLines(segments: readonly Segment[], tol: number, byColor: boolean): Line[] {
  const groups: { origin: Vec3; dir: Vec3; color: string; spans: [number, number][] }[] = [];
  for (const s of segments) {
    const v = sub(s.to, s.from);
    const l = len(v);
    if (l < 1e-9) continue;
    let dir: Vec3 = [v[0] / l, v[1] / l, v[2] / l];
    const lead = dir.find((c) => Math.abs(c) > 1e-6) ?? 1;
    if (lead < 0) dir = [-dir[0], -dir[1], -dir[2]];
    const color = byColor ? s.color : "";
    let g = groups.find((g) => {
      if (g.color !== color) return false;
      const cross = len([g.dir[1] * dir[2] - g.dir[2] * dir[1], g.dir[2] * dir[0] - g.dir[0] * dir[2], g.dir[0] * dir[1] - g.dir[1] * dir[0]]);
      if (cross > 1e-3) return false;
      const off = sub(s.from, g.origin);
      const perp = sub(off, [g.dir[0] * dot(off, g.dir), g.dir[1] * dot(off, g.dir), g.dir[2] * dot(off, g.dir)]);
      return len(perp) <= tol;
    });
    if (!g) {
      g = { origin: s.from, dir, color, spans: [] };
      groups.push(g);
    }
    const t0 = dot(sub(s.from, g.origin), g.dir);
    const t1 = dot(sub(s.to, g.origin), g.dir);
    g.spans.push(t0 < t1 ? [t0, t1] : [t1, t0]);
  }
  const lines: Line[] = [];
  for (const g of groups) {
    g.spans.sort((p, q) => p[0] - q[0]);
    let cur = [...g.spans[0]] as [number, number];
    const flush = () => lines.push({ a: addk(g.origin, g.dir, cur[0]), b: addk(g.origin, g.dir, cur[1]), color: g.color });
    for (const sp of g.spans.slice(1)) {
      if (sp[0] <= cur[1] + tol) cur[1] = Math.max(cur[1], sp[1]);
      else {
        flush();
        cur = [...sp] as [number, number];
      }
    }
    flush();
  }
  return lines;
}

function box(lines: Line[]): { min: Vec3; max: Vec3 } {
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (const l of lines)
    for (const p of [l.a, l.b])
      for (let i = 0; i < 3; i++) {
        min[i] = Math.min(min[i], p[i]);
        max[i] = Math.max(max[i], p[i]);
      }
  return { min, max };
}

const PLANE_TRANSFORMS: ((p: Vec3) => Vec3)[] = [
  ([x, y, z]) => [x, y, z],
  ([x, y, z]) => [-y, x, z],
  ([x, y, z]) => [-x, -y, z],
  ([x, y, z]) => [y, -x, z],
  ([x, y, z]) => [-x, y, z],
  ([x, y, z]) => [y, x, z],
  ([x, y, z]) => [x, -y, z],
  ([x, y, z]) => [-y, -x, z],
];

/** Pair drawn lines with expected ones; returns the pairs and what is left over. */
function match(drawn: Line[], expected: Line[], tol: number) {
  const used = new Set<number>();
  const pairs: [Line, Line][] = [];
  let missing = 0;
  for (const e of expected) {
    const i = drawn.findIndex(
      (d, k) => !used.has(k) && ((dist(d.a, e.a) <= tol && dist(d.b, e.b) <= tol) || (dist(d.a, e.b) <= tol && dist(d.b, e.a) <= tol)),
    );
    if (i === -1) missing++;
    else {
      used.add(i);
      pairs.push([d(drawn, i), e]);
    }
  }
  return { pairs, missing, extra: drawn.length - used.size };
}
const d = (lines: Line[], i: number) => lines[i];

const num = (n: number) => {
  const r = Math.round(n * 10) / 10;
  return (Number.isInteger(r) ? String(r) : r.toFixed(1)).replace(".", ",");
};
const plural = (n: number, one: string, few: string, many: string) =>
  n === 1 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) ? few : many;

/** Usage of a keyword anywhere in the program (outside comments). */
export function usesKeyword(source: string, keyword: Keyword): boolean {
  const code = source.replace(/;[^\n]*/g, " ").replace(/"[^"\n]*"?/g, " ");
  for (const m of code.matchAll(/[\p{L}_][\p{L}\p{N}_]*/gu)) if (keywordOf(m[0].toLowerCase()) === keyword) return true;
  return false;
}

/** Compare a learner's attempt with the expected drawing and explain the verdict in Polish. */
export function checkAttempt(attempt: { source: string; result: RunResult }, options: CheckOptions): CheckResult {
  const { result } = attempt;
  if (result.error)
    return {
      pass: false,
      reason: `Program zatrzymał się na błędzie (wiersz ${result.error.line}, kolumna ${result.error.column}): ${result.error.message}`,
    };
  const expectedRaw = maximalLines(options.expected, 1e-6, false);
  const eb = box(expectedRaw);
  const diag = dist(eb.min, eb.max);
  const tol = Math.max(1, diag * 0.01);
  const byColor = !!options.checkColor;
  const expected = maximalLines(options.expected, tol / 4, byColor);
  const drawnLines = maximalLines(result.segments, tol / 4, byColor);
  if (drawnLines.length === 0) return { pass: false, reason: "Nic nie zostało narysowane. Czy pisak jest opuszczony (opu)?" };

  const transforms = options.space ? [PLANE_TRANSFORMS[0]] : PLANE_TRANSFORMS;
  const center = (b: { min: Vec3; max: Vec3 }): Vec3 => [(b.min[0] + b.max[0]) / 2, (b.min[1] + b.max[1]) / 2, (b.min[2] + b.max[2]) / 2];
  const ec = center(box(expected));
  let best: { missing: number; extra: number; pairs: [Line, Line][] } | null = null;
  for (const t of transforms) {
    const moved = drawnLines.map((l) => ({ ...l, a: t(l.a), b: t(l.b) }));
    const shift = sub(ec, center(box(moved)));
    const aligned = moved.map((l) => ({ ...l, a: addk(l.a, shift, 1), b: addk(l.b, shift, 1) }));
    const m = match(aligned, expected, tol);
    if (!best || m.missing + m.extra < best.missing + best.extra) best = m;
    if (m.missing === 0 && m.extra === 0) break;
  }

  if (best && best.missing === 0 && best.extra === 0) {
    if (byColor) {
      const wrong = best.pairs.find(([a, e]) => a.color !== e.color);
      if (wrong)
        return { pass: false, reason: `Kształt się zgadza, ale kolor nie: we wzorze jest ${wrong[1].color}, a na rysunku ${wrong[0].color}.` };
    }
    for (const r of options.requires ?? [])
      if (!usesKeyword(attempt.source, r.keyword)) return { pass: false, reason: `Rysunek się zgadza, ale to jeszcze nie wszystko. ${r.hint}` };
    return { pass: true, reason: "Zaliczone! Rysunek zgadza się ze wzorem." };
  }

  // Explain the most useful difference first: size, then missing and extra lines.
  const db = box(drawnLines);
  const dims = (b: { min: Vec3; max: Vec3 }) => {
    const sizes = [b.max[0] - b.min[0], b.max[1] - b.min[1]];
    if (options.space) sizes.push(b.max[2] - b.min[2]);
    return sizes;
  };
  const ds = dims(db);
  const es = dims(box(expected));
  const sorted = (a: number[]) => [...a].sort((p, q) => p - q);
  const sameSize = options.space
    ? ds.every((v, i) => Math.abs(v - es[i]) <= tol)
    : sorted(ds).every((v, i) => Math.abs(v - sorted(es)[i]) <= tol);
  if (!sameSize)
    return {
      pass: false,
      reason: `Rysunek ma wymiary ${ds.map(num).join(" × ")}, a wzór ${es.map(num).join(" × ")}. Sprawdź długości kroków.`,
    };
  const parts: string[] = [];
  const { missing, extra } = best!;
  if (missing) parts.push(`Brakuje ${missing} ${plural(missing, "odcinka", "odcinków", "odcinków")} wzoru.`);
  if (extra) parts.push(`Narysowano ${extra} ${plural(extra, "odcinek nadmiarowy", "odcinki nadmiarowe", "odcinków nadmiarowych")}, których nie ma we wzorze.`);
  return { pass: false, reason: `${parts.join(" ")} Porównaj rysunek z przerywanymi liniami wzoru.` };
}
