import { checkAttempt } from "../challenges/checker";
import { readJSON, writeJSON, type KeyValueStore } from "../app/store";
import { href } from "../app/router";
import { CHALLENGES, targetOf, type Challenge } from "../content/challenges";
import { renderStill } from "../views/view2d";
import { h } from "./dom";
import { icon } from "./icons";
import type { StudioPage } from "./studio-page";

interface Progress {
  passed?: boolean;
  attempt?: string;
}
type ProgressMap = Record<string, Progress>;

export function readProgress(store: KeyValueStore): ProgressMap {
  return readJSON<ProgressMap>(store, "challenges", {});
}

function saveProgress(store: KeyValueStore, id: string, patch: Progress) {
  const all = readProgress(store);
  all[id] = { ...all[id], ...patch };
  writeJSON(store, "challenges", all);
}

const starterFor = (ch: Challenge) => `; Wyzwanie: ${ch.title}\n; ${ch.task}\n\n`;

/** The list of practice tasks: target as fold lines, state, and a way in. */
export function challengesPage(store: KeyValueStore): HTMLElement {
  const progress = readProgress(store);
  const done = CHALLENGES.filter((c) => progress[c.id]?.passed).length;
  const card = (ch: Challenge, i: number) => {
    const passed = !!progress[ch.id]?.passed;
    const thumb = renderStill({ segments: [], turtle: null, tween: null, ghost: targetOf(ch) }, ch.mode === "2d" ? "top" : "iso", 240, 170, {
      dpr: Math.min(2, globalThis.devicePixelRatio || 1),
      padding: 18,
    });
    thumb.className = "thumb";
    thumb.setAttribute("role", "img");
    thumb.setAttribute("aria-label", `Wzór do narysowania: ${ch.title}`);
    const id = `ch-${ch.id}`;
    return h(
      "li",
      { class: `sheet-card challenge-item${passed ? " is-passed" : ""}`, "data-challenge": ch.id },
      h("div", { class: "sheet-card-thumb" }, thumb),
      h(
        "div",
        { class: "sheet-card-body" },
        h("h3", { class: "sheet-card-title", id }, h("a", { href: href.challenge(ch.id), class: "stretched" }, `${i + 1}. ${ch.title}`)),
        h("p", { class: "sheet-card-note" }, ch.task),
        h(
          "p",
          { class: "sheet-card-meta" },
          h("span", { class: `mode-chip mode-${ch.mode}` }, ch.mode.toUpperCase()),
          h("span", { class: `state-chip ${passed ? "state-pass" : "state-todo"}` }, passed ? icon("check") : icon("target"), passed ? "Zaliczone" : "Do zrobienia"),
        ),
      ),
    );
  };
  return h(
    "div",
    { class: "page page-challenges" },
    h(
      "header",
      { class: "page-head" },
      h("h1", {}, "Wyzwania"),
      h(
        "p",
        { class: "lead" },
        "Przerywane linie pokazują, co narysować. Napisz program, naciśnij «Sprawdź», a Logomocja porówna rysunek ze wzorem. Liczy się kształt i wielkość, nie miejsce na kartce ani kolejność rysowania.",
      ),
      h("p", { class: "progress-line", "data-role": "progress" }, `Zaliczone: ${done} z ${CHALLENGES.length}`),
    ),
