  );
}

/** Wire a challenge into the studio and render its card above the run bar. */
export function openChallenge(ch: Challenge, studio: StudioPage, store: KeyValueStore, slot: HTMLElement, onExit: () => void): void {
  const index = CHALLENGES.indexOf(ch);
  const stored = readProgress(store)[ch.id];
  const result = h("p", { class: "challenge-result", role: "status", "aria-live": "polite" });
  let ghostOn = true;
  const showGhost = h("button", { type: "button", class: "btn btn-quiet", "aria-pressed": "true", "data-action": "toggle-target" }, icon("target"), "Wzór");
  const hint = h("p", { class: "challenge-hint", hidden: true }, ch.hint);
  const hintButton = h(
    "button",
    { type: "button", class: "btn btn-quiet", "aria-expanded": "false", onclick: () => {
      hint.hidden = !hint.hidden;
      hintButton.setAttribute("aria-expanded", String(!hint.hidden));
    } },
    icon("info"),
    "Podpowiedź",
  );
  const ctx = {
    id: ch.id,
    mode: ch.mode,
    title: ch.title,
    ghost: targetOf(ch),
    text: stored?.attempt ?? starterFor(ch),
    save: (text: string) => saveProgress(store, ch.id, { attempt: text }),
  };
