    result.className = `challenge-result ${verdict.pass ? "is-pass" : "is-fail"}`;
    result.replaceChildren(icon(verdict.pass ? "check" : "cross"), h("span", {}, verdict.pass ? verdict.reason : `Jeszcze nie. ${verdict.reason}`));
    if (verdict.pass) saveProgress(store, ch.id, { passed: true, attempt: source });
  };
  slot.replaceChildren(
    h(
      "section",
      { class: "challenge-card", "aria-labelledby": "challenge-title" },
      h(
        "div",
        { class: "challenge-head" },
        h("h2", { id: "challenge-title" }, ch.title),
        h("span", { class: "challenge-count" }, `Wyzwanie ${index + 1} z ${CHALLENGES.length}`),
        stored?.passed ? h("span", { class: "state-chip state-pass" }, icon("check"), "Zaliczone") : null,
      ),
      h("p", { class: "challenge-task" }, ch.task),
      hint,
      h(
        "div",
        { class: "challenge-actions" },
        h("button", { type: "button", class: "btn", "data-action": "check", onclick: () => void check() }, icon("check"), "Sprawdź"),
        showGhost,
        hintButton,
        h(
          "button",
          { type: "button", class: "btn btn-quiet challenge-exit", "data-action": "exit-challenge", onclick: () => onExit() },
          icon("exit"),
          "Zakończ",
        ),
      ),
      result,
    ),
  );
  studio.enterChallenge(ctx);
}
