import { href } from "../app/router";
import { REFERENCE, ENGLISH, type Block, type CommandDoc } from "../content/reference";
import type { Mode } from "../lang";
import { FAMILY } from "../lang/highlight";
import { ALIASES } from "../lang/keywords";
import { codeBlock } from "./code";
import { h } from "./dom";
import { icon } from "./icons";
import { kbd, SHORTCUTS } from "./studio-page";

/** Inline `code` in prose. */
function prose(text: string): (Node | string)[] {
  return text.split(/`([^`]+)`/).map((part, i) => (i % 2 ? h("code", { class: "inline" }, part) : part));
}

type TryFn = (source: string, mode: Mode, title: string) => void;

function example(source: string, mode: Mode, title: string, onTry: TryFn): HTMLElement {
  return h(
    "figure",
    { class: "example", "data-example-source": source, "data-example-mode": mode },
    codeBlock(source, `Przykład: ${title}`),
    h(
      "figcaption",
      {},
      h("span", { class: `mode-chip mode-${mode}` }, mode.toUpperCase()),
      h("button", { type: "button", class: "btn btn-quiet", "data-action": "try", onclick: () => onTry(source, mode, title) }, icon("play"), "Wypróbuj", h("span", { class: "visually-hidden" }, `: ${title}`)),
    ),
  );
}

function block(b: Block, onTry: TryFn): HTMLElement {
  if ("p" in b) return h("p", {}, ...prose(b.p));
  if ("list" in b) return h("ul", {}, ...b.list.map((li) => h("li", {}, ...prose(li))));
  if ("code" in b) return example(b.code, b.mode ?? "2d", b.title ?? "przykład", onTry);
  return h(
    "div",
    { class: "table-wrap" },
    h(
      "table",
      {},
      h("thead", {}, h("tr", {}, ...b.table.head.map((c) => h("th", { scope: "col" }, c)))),
      h("tbody", {}, ...b.table.rows.map((r) => h("tr", {}, ...r.map((c, i) => (i === 0 ? h("th", { scope: "row" }, h("code", { class: "inline" }, c)) : h("td", {}, c)))))),
    ),
  );
}

function command(doc: CommandDoc, onTry: TryFn): HTMLElement {
  const spellings: readonly string[] = ALIASES[doc.keyword];
  const polish = spellings.filter((s) => !ENGLISH.has(s));
  const english = spellings.filter((s) => ENGLISH.has(s));
  const main = polish[0] ?? english[0];
  const fam = FAMILY[doc.keyword];
  const others = polish.slice(1);
  return h(
    "article",
    { class: `cmd fam-${fam}`, "data-command": doc.keyword, id: `cmd-${doc.keyword}` },
    h(
      "header",
      { class: "cmd-head" },
      h("h3", { class: "cmd-name" }, h("code", { class: `tok-${fam}` }, main)),
      h(
        "p",
        { class: "cmd-aliases" },
        others.length ? h("span", {}, "też ", ...others.flatMap((s, i) => [i ? ", " : "", h("code", { class: "inline" }, s)])) : null,
        english.length && polish.length && main !== "stop"
          ? h("span", {}, "po angielsku ", ...english.flatMap((s, i) => [i ? ", " : "", h("code", { class: "inline" }, s)]))
          : main === "stop"
            ? h("span", {}, "tak samo po angielsku")
            : null,
      ),
      h("p", { class: "cmd-arg" }, h("span", { class: "cmd-arg-label" }, "Argument: "), doc.args),
    ),
    h("p", { class: "cmd-summary" }, ...prose(doc.summary)),
    ...(doc.details ?? []).map((d) => h("p", {}, ...prose(d))),
    example(doc.example, doc.mode ?? "2d", main, onTry),
  );
}

/** The reference: a contents rail and a calm reading column. */
export function helpPage(section: string | null, onTry: TryFn): HTMLElement {
  const sections = [
    ...REFERENCE.map((s) =>
      h(
        "section",
        { id: s.id, class: "ref-section", "aria-labelledby": `h-${s.id}` },
        h("h2", { id: `h-${s.id}` }, s.title),
        ...s.intro.map((b) => block(b, onTry)),
        ...(s.commands ?? []).map((c) => command(c, onTry)),
        ...(s.after ?? []).map((b) => block(b, onTry)),
      ),
    ),
    h(
      "section",
      { id: "skroty", class: "ref-section", "aria-labelledby": "h-skroty" },
      h("h2", { id: "h-skroty" }, "Skróty klawiszowe"),
      h("p", {}, "Skróty działają w całym studiu, także gdy piszesz w edytorze. Na Macu zamiast Ctrl użyj ⌘."),
      h(
        "div",
        { class: "table-wrap" },
        h(
          "table",
          {},
          h("thead", {}, h("tr", {}, h("th", { scope: "col" }, "Co"), h("th", { scope: "col" }, "Klawisze"))),
          h(
            "tbody",
            {},
            ...SHORTCUTS.map(([what, keys]) => h("tr", {}, h("th", { scope: "row" }, what), h("td", {}, ...kbd(keys)))),
            h("tr", {}, h("th", { scope: "row" }, "Przesuń arkusz"), h("td", {}, "strzałki, gdy arkusz jest zaznaczony")),
            h("tr", {}, h("th", { scope: "row" }, "Skala arkusza"), h("td", {}, ...kbd("+"), " i ", ...kbd("−"))),
            h("tr", {}, h("th", { scope: "row" }, "Dopasuj rysunek"), h("td", {}, ...kbd("0"))),
          ),
        ),
      ),
    ),
  ];
  const toc = h(
    "nav",
    { class: "ref-toc", "aria-label": "Spis treści pomocy" },
    h("p", { class: "ref-toc-title" }, "Spis treści"),
    h(
      "ol",
      {},
      ...[...REFERENCE.map((s) => [s.id, s.title] as const), ["skroty", "Skróty klawiszowe"] as const].map(([id, title]) =>
        h("li", {}, h("a", { href: href.help(id), "aria-current": id === section ? "true" : null }, title)),
      ),
    ),
  );
  const page = h(
    "div",
    { class: "page page-help" },
    toc,
    h(
      "article",
      { class: "ref" },
      h(
        "header",
        { class: "page-head" },
        h("h1", {}, "Pomoc: język Logomocji"),
        h("p", { class: "lead" }, "Wszystkie polecenia żółwia z przykładami. Każdy przykład można od razu uruchomić przyciskiem «Wypróbuj»; Twój szkic trafi wtedy do kopii."),
      ),
      ...sections,
    ),
  );
  if (section)
    queueMicrotask(() => {
      const target = page.querySelector<HTMLElement>(`#${CSS.escape(section)}`);
      target?.scrollIntoView?.({ block: "start" });
    });
  return page;
}
EOF
