cat >> tests/app.test.ts <<'EOF'

describe("keyboard and accessibility", () => {
  const key = (k: string, opts: KeyboardEventInit = {}) =>
    document.activeElement!.dispatchEvent(new KeyboardEvent("keydown", { key: k, bubbles: true, cancelable: true, ctrlKey: true, ...opts }));

  test("shortcuts run, step, pause and reset, and are listed in the studio", async () => {
    const { root, clock } = boot();
    await (window as any).logomocja.open("powtorz 10 [np 10 pw 36]", "2d");
    root.querySelector<HTMLElement>(".cm-content")!.focus();
    key("Backspace", { shiftKey: true });
    expect(segmentCount(root)).toBe("0 odcinków");
    key("Enter", { shiftKey: true });
    expect(status(root)).toContain("Pauza");
    key(" ", { shiftKey: true, code: "Space" });
    expect(status(root)).toContain("rysuje");
    key(" ", { shiftKey: true, code: "Space" });
    expect(status(root)).toContain("Pauza");
    key("Enter");
    clock.advance(60_000);
    expect(segmentCount(root)).toBe("10 odcinków");
    const listed = root.querySelector("#shortcuts-panel")!.textContent!;
    for (const what of ["Uruchom", "Krok", "Pauza", "Od nowa"]) expect(listed).toContain(what);
  });

  test("without WebGL the 3D sheet says why, and still draws a flat projection", async () => {
    const { root } = boot();
    const result = await (window as any).logomocja.open("gora 90 np 50", "3d");
    expect(result.error).toBeNull();
    expect(root.querySelector(".sheet-notice")!.textContent).toContain("WebGL");
    expect(segmentCount(root)).toBe("1 odcinek");
  });

  test("every control on every page has an accessible name", async () => {
    const { root } = boot();
    const unnamed = () =>
      [...root.querySelectorAll<HTMLElement>("button, a[href], input:not([aria-hidden='true']), select, textarea")]
        .filter((el) => !el.closest("[hidden]"))
        .filter((el) => {
          const label = el.getAttribute("aria-label") || el.textContent?.trim() || (el.id && root.querySelector(`label[for="${el.id}"]`)?.textContent);
          return !label;
        })
        .map((el) => el.outerHTML.slice(0, 80));
    expect(unnamed()).toEqual([]);
    for (const page of ["#/przyklady", "#/wyzwania", "#/pomoc", "#/wyzwania/kwadrat"]) {
      await navigate(page);
      expect(unnamed(), page).toEqual([]);
    }
  });
});
EOF
