// Minimal DOM shims so the app's real paint code runs against a headless canvas.
(globalThis as any).document = { createElement: (tag: string) => { if (tag !== "canvas") throw new Error(tag); const c: any = createCanvas(1, 1); return c; } };
(globalThis as any).getComputedStyle = () => ({ getPropertyValue: () => "" });

const { renderStill } = await import("/work/src/views/view2d.ts");
const { EXAMPLES } = await import("/work/src/content/examples.ts");
const { start } = await import("/work/src/lang/index.ts");

