  const scene = { segments: execution.segments, turtle: execution.turtleState, tween: null, ghost: [] };
  const canvas: any = renderStill(scene as any, ex.mode === "2d" ? "top" : "iso", 560, 400, { dpr: 1, padding: 28, grid: true, marks: true });
  writeFileSync(`/tmp/verify/out/${ex.id}.png`, canvas.toBuffer("image/png"));
}
