cat >> tests/interpreter.test.ts <<'EOF'

describe("details from the brief", () => {
  test("nrpowt in a procedure body outside its own repeat is a parse error, even if called from a repeat", () => {
    const e = failure("oto p\n  np nrpowt\njuż\npowtorz 3 [p]");
    expect(pos(e)).toEqual([2, 6]);
    expect(e.segments).toEqual([]);
    expect(run("oto p\n  powtorz 2 [np nrpowt]\njuż\npowtorz 3 [p]", "2d").error).toBeNull();
  });
  test("conditional bodies count towards the bracket nesting limit", () => {
    const nest = (n: number) => "jeśli 1 = 1 [".repeat(n) + "np 1" + "]".repeat(n);
    expect(run(nest(32), "2d").error).toBeNull();
    expect(pos(failure(nest(33)))).toEqual([1, 32 * 13 + 13]);
  });
  test("a run-time error keeps only what was drawn after the last czyść", () => {
    const e = failure("np 10 czyść pw 90 np 5 np 1 / 0");
    expect(e.segments).toEqual([{ from: [0, 10, 0], to: [5, 10, 0], color: GREEN, width: 3 }]);
  });
  test("a literal too large to represent is an error at the argument", () => {
    const e = failure(`np 1\nnp ${"9".repeat(400)}`);
    expect(pos(e)).toEqual([2, 4]);
    expect(e.segments.length).toBe(1);
  });
});
EOF
